	["[text]  write a note in your journal here and now, or open the quick note card"] = "[텍스트]  지금 여기서 일지에 메모를 쓰거나 빠른 메모 카드 열기",
	["A button on keepsake and level moments. A click closes the card and takes a screenshot without it. Nothing is taken by itself."] = "기념품과 레벨 순간에 나오는 버튼입니다. 클릭하면 카드를 닫고 카드 없이 스크린샷을 찍습니다. 저절로 찍히는 것은 없습니다.",
	["A check is already running."] = "이미 확인이 진행 중입니다.",
	["A companion's recorded time is outside the supported range."] = "동료의 기록된 시간이 지원 범위를 벗어났습니다.",
	["a cooldown kept for hard fights"] = "어려운 전투용으로 아껴 둔 재사용 대기시간",
	["A corner of %s"] = "%s의 구석",
	["A creature of this event."] = "이 이벤트의 생물입니다.",
	["A creature or chest that drops the recipe."] = "제조법을 떨어뜨리는 생물이나 상자입니다.",
	["A dungeon"] = "던전",
	["a dungeon"] = "던전",
	["A first boss kill waits at the end of a dungeon. These fit your level:"] = "던전 끝에서 첫 우두머리 처치가 기다립니다. 내 레벨에 맞는 곳:",
	["A friend or group member..."] = "친구나 파티원...",
	["A Journal button on the minimap: left-click opens My Adventure, right-click writes a quick note, drag it to move it around the edge. The Minimap module's button bin gathers it."] = "미니맵의 일지 버튼: 왼쪽 클릭은 나의 모험을 열고, 오른쪽 클릭은 빠른 메모를 쓰며, 드래그하면 가장자리를 따라 움직입니다. 미니맵 모듈의 버튼 모음에 들어갑니다.",
	["A Journal button under EldoUI's in the Esc menu: click opens My Adventure, right-click writes a quick note."] = "Esc 메뉴의 EldoUI 버튼 아래에 있는 일지 버튼: 클릭은 나의 모험을 열고, 오른쪽 클릭은 빠른 메모를 씁니다.",
	["A journal kept since %s."] = "%s부터 쓴 일지.",
	["A letter from the Scarshield Quartermaster in Blackrock Spire sends you to the orb behind General Drakkisath, which opens Blackwing Lair."] = "검은바위 첨탑에 있는 흉터방패 병참장교의 편지가 드라키사스 장군 뒤의 보주로 안내하며, 그 보주가 검은날개 둥지를 엽니다.",
	["A line from your story under each chapter title and another after its moments, told in the tone you picked on the Story tab. Level view only."] = "각 장 제목 아래와 그 순간들 뒤에 이야기 한 줄씩, 이야기 탭에서 고른 어조로 들려줍니다. 레벨 보기 전용.",
	["A little high for you: a level %d quest."] = "조금 높음: 레벨 %d 퀘스트.",
	["A little high for you: it starts at level %d."] = "조금 높음: 레벨 %d부터 시작.",
	["A little low for you: it is %d-%d."] = "조금 낮음: 레벨 %d-%d.",
	["A long break"] = "긴 휴식",
	["a long cooldown kept for hard fights"] = "어려운 전투용으로 아껴 둔 긴 재사용 대기시간",
	["A milestone to look forward to."] = "기대할 만한 이정표.",
	["A moment in your journal"] = "일지의 순간",
	["A new goal"] = "새 목표",
	["A note"] = "메모",
	["A note remembers where and when you wrote it, and it can remind you later."] = "메모는 쓴 장소와 시간을 기억하고, 나중에 알려 줄 수 있습니다.",
	["A note remembers where and when you wrote it. It can remind you later."] = "메모는 쓴 장소와 시간을 기억합니다. 나중에 알려 줄 수 있습니다.",
	["a one-minute bane; Bane of Agony is used"] = "1분짜리 저주; 고통의 저주를 사용",
	["A one-time reminder moves to the archive once it has fired or you mark it done."] = "일회성 알림은 울리거나 완료로 표시하면 보관함으로 옮겨집니다.",
	["A page of My Adventure"] = "나의 모험 페이지",
	["A pin on the world map for each giver of the quests left in the zone the map shows. Hover it for the quests, click it for a waypoint. The map's EldoUI pin switch hides it with the other pins."] = "지도에 보이는 지역에서 남은 퀘스트를 주는 퀘스트 제공자마다 세계 지도에 표시합니다. 마우스를 올리면 퀘스트가, 클릭하면 경유지가 나옵니다. 지도의 EldoUI 표시 스위치로 다른 표시와 함께 숨길 수 있습니다.",
	["A pin where the next step of each attunement you are on starts. Click it for the arrow."] = "진행 중인 각 입장 자격의 다음 단계가 시작되는 곳에 표시합니다. 클릭하면 화살표가 나옵니다.",
	["A place in your journal"] = "일지의 장소",
	["a place to find"] = "찾을 장소",
	["a profession you do not have"] = "배우지 않은 전문 기술",
	["a quest"] = "퀘스트",
	["A quest counts once you both have it and one of its objectives moves forward while you are grouped."] = "둘 다 퀘스트를 가지고 있고 파티 중에 목표 하나가 진행되면 집계됩니다.",
	["A quest of this event."] = "이 이벤트의 퀘스트입니다.",
	["A quest outside dungeons, or a creature and what it drops."] = "던전 밖의 퀘스트, 또는 생물과 그 전리품.",
	["A quest that needs this standing."] = "이 평판이 필요한 퀘스트입니다.",
	["A quest that rewards the recipe."] = "제조법을 보상으로 주는 퀘스트입니다.",
	["a racial spell; not modeled"] = "종족 주문; 계산하지 않음",
	["a raid"] = "공격대",
	["A reached goal moves to the archive instead of staying in the Reached list."] = "달성한 목표는 달성 목록에 남지 않고 보관함으로 옮겨집니다.",
	["A reminder"] = "알림",
	["A sample step"] = "예시 단계",
	["A scroll above the name."] = "이름 위의 두루마리.",
	["A scroll in a bronze frame above the name, to match the WoW Forever art style."] = "이름 위에 청동 테두리를 두른 두루마리, WoW Forever 아트 스타일에 맞춤.",
	["A scroll, the quest giver's exclamation mark, a dot in your accent color, a scroll in a bronze frame, or a yellow square with a mark that reads for every kind of color blindness."] = "두루마리, 퀘스트 제공자의 느낌표, 강조 색상의 점, 청동 테두리 두루마리, 또는 모든 종류의 색맹에서 알아볼 수 있는 표시가 있는 노란 사각형.",
	["A short card when you enter a zone or a dungeon: your quests there, rares, your notes and your last run. Off in combat."] = "지역이나 던전에 들어갈 때 나오는 짧은 카드: 그곳의 내 퀘스트, 희귀 몹, 내 메모, 마지막 공략. 전투 중에는 꺼집니다.",
	["A short summary of the session during the logout countdown, also kept as a row in the Day view."] = "로그아웃 카운트다운 동안 세션을 짧게 요약하며, 하루 보기에도 한 줄로 남깁니다.",
	["A short tour of My Adventure."] = "나의 모험 둘러보기.",
	["A small dot in your accent color left of the bar."] = "막대 왼쪽에 강조 색상의 작은 점.",
	["A small icon on the nameplate of a creature that can drop a quest starter. Needs EldoUI's Nameplates module."] = "퀘스트를 시작하는 아이템을 떨어뜨릴 수 있는 생물의 이름표에 작은 아이콘. EldoUI의 Nameplates 모듈이 필요합니다.",
	["A small mark after each sentence; hover it to see the facts the sentence comes from."] = "문장마다 뒤에 붙는 작은 표시; 마우스를 올리면 그 문장의 근거가 된 사실을 봅니다.",
	["A solid dark page with no ornaments, numbers first."] = "장식 없는 어두운 단색 페이지, 숫자 우선.",
	["a spell"] = "주문",
	["A step of %s is here: %s."] = "%s의 단계가 여기 있습니다: %s.",
	["A step of %s is inside: %s."] = "%s의 단계가 안에 있습니다: %s.",
	["A string with this character's Best in Slot, plan sets, spec and talents (no name or realm) to share."] = "이 캐릭터의 Best in Slot, 계획 세트, 전문화, 특성을 담은 공유용 문자열 (이름이나 서버 없음).",
	["A strip over the chapters with a mark for each level and its big moments. Click a level to open its chapter. Shown in the level view while no search or filter is on."] = "장 위의 띠: 레벨마다, 그리고 큰 순간마다 표시가 있습니다. 레벨을 클릭하면 그 장을 엽니다. 검색이나 필터가 없을 때 레벨 보기에 표시됩니다.",
	["A to-do you check off yourself."] = "직접 체크하는 할 일.",
	["A toast or banner, a sound and a chat line when a wished item is in a loot window or a roll, or drops in the dungeon you enter. Set them in /eui > Loot Guide."] = "위시리스트 아이템이 전리품 창이나 주사위 굴림에 있거나, 들어간 던전에서 나올 때 알림 또는 배너, 소리, 대화창 한 줄. /eui > Loot Guide에서 설정하세요.",
	["A toast when you finish a step or a whole attunement. Nothing is posted to chat."] = "단계나 입장 자격 전체를 마치면 알림을 띄웁니다. 대화창에는 아무것도 올리지 않습니다.",
	["A trainer who teaches this recipe."] = "이 제조법을 가르치는 전문가입니다.",
	["A vendor during this event."] = "이 이벤트 동안의 상인입니다.",
	["A vendor for these rewards."] = "이 보상들을 파는 상인입니다.",
	["A vendor who sells the recipe."] = "이 제조법을 파는 상인입니다.",
	["A yellow square with a mark above the name; the shape carries it too."] = "이름 위에 표시가 있는 노란 사각형; 모양으로도 구별됩니다.",
	["A zone, or a spot inside one like Frostmane Hold."] = "지역 또는 그 안의 장소 (예: 서리갈기 요새).",
	["Abandoned"] = "포기함",
	["Abandoned quests"] = "포기한 퀘스트",
	["Abandoned, failed, or removed by the game. The journal only lists them; nothing is picked up again for you."] = "포기했거나, 실패했거나, 게임이 없앤 퀘스트. 일지는 목록만 보여 주며, 대신 다시 받아 주지 않습니다.",
	["About %s of play at your recent pace. It counts your own last levels only."] = "최근 속도로 약 %s 플레이. 내 최근 레벨만 셉니다.",
	["About %s per kill."] = "처치당 약 %s.",
	["About as good as what you wear"] = "지금 착용한 것과 비슷함",
	["About the same"] = "거의 같음",
	["About this zone"] = "이 지역에 대해",
	["Above the name"] = "이름 위",
	["Accept merges it into this character's journal: nothing is lost, and a backup is taken first."] = "수락하면 이 캐릭터의 일지에 합칩니다: 아무것도 잃지 않으며, 먼저 백업을 만듭니다.",
	["account"] = "계정",
	["Active goals"] = "진행 중인 목표",
	["active now"] = "지금 진행 중",
	["Active now"] = "지금 진행 중",
	["Active now and start dates: from the game's calendar."] = "지금 진행 중과 시작 날짜: 게임 달력 기준.",
	["Barrow Deeps"] = "Barrow Deeps",
	["Beta data ties it to a prison area in the raid; the game has not confirmed it yet."] = "베타 데이터는 공격대의 감옥 구역과 연결하지만, 게임에서 아직 확인되지 않았습니다.",
	["Brooch of the Wardens"] = "Brooch of the Wardens",
	["Every raid member needs their own Drakefire Amulet."] = "공격대원마다 각자 목걸이가 필요합니다.",
	["Forever raid"] = "Forever 공격대",
	["Getting ready"] = "준비",
	["Hyjal Summit"] = "하이잘 정상",
	["in your bags or bank"] = "가방 또는 은행에 있음",
	["Next reward at %s: %s"] = "%s 단계 다음 보상: %s",
	["No attunement announced"] = "발표된 입장 자격 없음",
	["no standing yet"] = "아직 평판 없음",
	["not held"] = "없음",
	["Notes the quests, dungeons, zone level ranges and rares the game shows you that the guide does not know yet, so the guide can show them. Reads only dialogs, the map and your target."] = "게임이 보여 주지만 안내서 데이터가 아직 모르는 퀘스트, 던전, 지역 레벨 범위와 희귀 몹을 기록해 안내서가 보여 줄 수 있게 합니다. 대화창, 지도, 대상으로 잡은 생물이 보여 주는 것만 읽습니다.",
	["Open now."] = "지금 열려 있습니다.",
	["Opens %s."] = "%s에 열립니다.",
	["Opens the Attunements tab on what you can get ready for it."] = "지금 준비할 수 있는 것을 입장 자격 탭에서 엽니다.",
	["starts %s"] = "%s 시작",
	["add it to the planner on the right"] = "오른쪽 계획표에 추가",
	["Add my BiS"] = "내 BiS 추가",
	["Add note"] = "메모 추가",
	["add or remove this from the filter"] = "필터에 추가하거나 빼기",
	["add or remove this item"] = "이 아이템 추가 또는 빼기",
	["Add to wishlist"] = "위시리스트에 추가",
	["Add wishlist note"] = "위시리스트 메모 추가",
	["Added %d best-in-slot items to your wishlist."] = "Best in Slot 아이템 %d개를 위시리스트에 추가했습니다.",
	["Added %d items to %s."] = { other = "%d개를 %s에 추가했습니다." },
	["Added %d pieces of %s to your wishlist."] = { other = "%d부위의 %s 세트를 위시리스트에 추가했습니다." },
	["Added %d PvP items from your wishlist to the planner."] = "위시리스트의 PvP 아이템 %d개를 계획표에 추가했습니다.",
	["Added %s to %s."] = "%s 항목을 %s에 추가했습니다.",
	["Adds a button to the toast that posts one line in guild chat when you click it."] = "클릭하면 길드 대화에 한 줄을 올리는 버튼을 알림에 추가합니다.",
	["Adds a Need, Greed or Pass word to that box. It is a label only and never rolls for you."] = "그 칸에 입찰, 차비, 포기 중 한 단어를 붙입니다. 표시일 뿐이며 대신 주사위를 굴리지 않습니다.",
	["Adds a Quests line (done of total) to Zone Info's world map tooltip when you hover a zone. Needs the Zone Info module."] = "지역에 마우스를 올리면 Zone Info의 세계 지도 툴팁에 퀘스트 줄(완료/전체)을 추가합니다. Zone Info 모듈이 필요합니다.",
	["Adds it to your goals, so the tracker and the Goals page follow it."] = "목표에 추가하여 추적기와 목표 페이지가 따라갑니다.",
	["Adds the best-in-slot items for your spec that you do not own and have not wished for yet."] = "내 전문화의 Best in Slot 아이템 중 가지고 있지 않고 아직 찜하지 않은 것을 추가합니다.",
	["Adds the item to your active wishlist, or takes it off every list on show."] = "아이템을 활성 위시리스트에 추가하거나, 표시된 모든 목록에서 뺍니다.",
	["Adds the item to your active wishlist, or takes it off."] = "아이템을 활성 위시리스트에 추가하거나 뺍니다.",
	["Adds the PvP rewards on your active wishlist to the planner."] = "활성 위시리스트의 PvP 보상을 계획표에 추가합니다.",
	["Advice only: you roll yourself."] = "조언일 뿐: 주사위는 직접 굴립니다.",
	["After 12 hours away"] = "12시간 자리를 비운 뒤",
	["After 4 hours away"] = "4시간 자리를 비운 뒤",
	["After a break, Today starts with a card about your last session: where you were, your level, and its best moment. Never: no card."] = "쉬고 돌아오면 오늘이 지난 세션 카드로 시작합니다: 있던 곳, 레벨, 가장 좋은 순간. 안 함: 카드 없음.",
	["After a day away"] = "하루 자리를 비운 뒤",
	["After an hour away"] = "한 시간 자리를 비운 뒤",
	["After: %s"] = "이후: %s",
	["Afterwards"] = "이후",
	["Agility"] = "민첩성",
	["Ahn'Qiraj sets"] = "안퀴라즈 세트",
	["Aimed Shot, Multi-Shot and Arcane Shot"] = "조준 사격, 일제 사격, 신비한 사격",
	["Alcaz Prison"] = "Alcaz Prison",
	["Alchemy"] = "연금술",
	["Alert card with a button"] = "버튼이 있는 알림 카드",
	["Alert sound"] = "알림 소리",
	["Alerts"] = "알림",
	["Alerts off"] = "알림 끔",
	["Alerts on (%s)"] = "알림 켬 (%s)",
	["All"] = "전체",
	["All %d ideas"] = { other = "아이디어 %d개 전부" },
	["All classes"] = "모든 직업",
	["All groups"] = "모든 그룹",
	["All instances"] = "모든 인스턴스",
	["All kinds"] = "모든 종류",
	["All of them on the Goals page."] = "모두 목표 페이지에 있습니다.",
	["All sets"] = "모든 세트",
	["All steps above"] = "위의 모든 단계",
	["All upgrades"] = "모든 상위 장비",
