	["Dungeon sets"] = "던전 세트",
	["Dungeon, group, elite, and solo quests; in progress: ready or still to do."] = "던전, 파티, 정예, 혼자 하는 퀘스트; 진행 중: 완료 가능 또는 남음.",
	["dungeons"] = "던전",
	["Dungeons"] = "던전",
	["Dungeons and raids"] = "던전 및 공격대",
	["Dungeons and raids the Instances module recorded."] = "인스턴스 모듈이 기록한 던전과 공격대.",
	["dungeons are off in your filter"] = "필터에서 던전이 꺼져 있습니다",
	["Dungeons here: %s"] = "이곳의 던전: %s",
	["Dungeons in reach: %s."] = { other = "갈 수 있는 던전: %s." },
	["Dungeons that fit your level, with their quests to take along."] = "내 레벨에 맞는 던전과 함께 챙길 퀘스트.",
	["Dungeons together"] = "함께한 던전",
	["Dungeons within this many levels of yours count as right for you now (tiles, the level bar and My level only)."] = "내 레벨에서 이 레벨 차 이내의 던전을 지금 알맞다고 봅니다 (타일, 레벨 막대, 내 레벨에만 적용).",
	["Dungeons, bosses, quests, zones, mobs and items."] = "던전, 우두머리, 퀘스트, 지역, 몹, 아이템.",
	["Dungeons, bosses, quests, zones, mobs and items. Results show as you type; Enter opens them all."] = "던전, 우두머리, 퀘스트, 지역, 몹, 아이템. 입력하는 대로 결과가 나오고 Enter를 누르면 모두 엽니다.",
	["Each quest you hand in is written here, with where and when."] = "완료 보고한 퀘스트를 장소, 시간과 함께 여기에 적습니다.",
	["Each run you make here is written down with its time, bosses, and company."] = "여기서 한 공략을 시간, 우두머리, 동행과 함께 적습니다.",
	["Earlier attunements"] = "이전 입장 자격",
	["Earlier moments"] = "이전 순간",
	["Earn %s gold"] = "%s골드 벌기",
	["Earn a standing"] = "평판 달성",
	["Earn gold"] = "골드 벌기",
	["Earned %s"] = "%s 획득",
	["Edit"] = "편집",
	["Edit note"] = "메모 편집",
	["Edit the note"] = "메모 편집",
	["Edit wishlist note"] = "위시리스트 메모 편집",
	["Editing a note from %s"] = "%s의 메모 편집 중",
	["EldoUI"] = "EldoUI",
	["EldoUI already knew %d moments of yours from %s: they are on your Journey."] = { other = "EldoUI가 %d개의 순간을 이미 %s에서 알고 있었습니다: 여정에 있습니다." },
	["EldoUI already knew %d moments of yours from its other records: they are on your Journey."] = { other = "EldoUI가 %d개의 순간을 이미 다른 기록에서 알고 있었습니다: 여정에 있습니다." },
	["EldoUI_LootData"] = "EldoUI_LootData",
	["EldoUI_LootData could not load"] = "EldoUI_LootData를 불러올 수 없음",
	["EldoUI_LootData is not installed"] = "EldoUI_LootData가 설치되지 않음",
	["EldoUI_LootData is switched off in the addon list"] = "애드온 목록에서 EldoUI_LootData가 꺼져 있음",
	["EldoUI_LootData is switched off in the addon list. Turn it on to see quest chains."] = "애드온 목록에서 EldoUI_LootData가 꺼져 있습니다. 켜면 연계 퀘스트를 볼 수 있습니다.",
	["EldoUI_LootData is too new or too old for this EldoUI"] = "EldoUI_LootData가 이 EldoUI에 비해 너무 새롭거나 오래됨",
	["EldoUI_LootData loads a few seconds after login"] = "EldoUI_LootData는 접속 몇 초 뒤에 불러옵니다",
	["EldoUI_LootSim could not load. Check that it is in Interface\\AddOns next to EldoUI."] = "EldoUI_LootSim을 불러올 수 없습니다. Interface\\AddOns에 EldoUI와 나란히 있는지 확인하세요.",
	["EldoUI_LootSim is switched off in the addon list."] = "애드온 목록에서 EldoUI_LootSim이 꺼져 있습니다.",
	["Elite"] = "정예",
	["Emptied the list %s."] = "%s 목록을 비웠습니다.",
	["Empties the set."] = "세트를 비웁니다.",
	["Empty"] = "비어 있음",
	["Empty slot"] = "빈 칸",
	["Empty slot: click to pick"] = "빈 칸: 클릭해서 고르기",
	["Empty the list on show. The other lists stay. Asks first."] = "표시된 목록을 비웁니다. 다른 목록은 그대로입니다. 먼저 확인합니다.",
	["Empty the planner. Asks first."] = "계획을 비웁니다. 먼저 확인합니다.",
	["empty: you keep what you wear"] = "비어 있음: 착용 중인 것을 유지",
	["Enable"] = "사용",
	["Enchanting"] = "마법부여",
	["Ends"] = "종료",
	["Ends at %s"] = "%s에 종료",
	["Ends the tour. Start it again with /eui tour journal."] = "둘러보기를 끝냅니다. /eui tour journal로 다시 시작하세요.",
	["Ends the tour. Start it again with Start tour on the Loot Guide settings page or /eui tour lootguide."] = "둘러보기를 끝냅니다. Loot Guide 설정 페이지의 둘러보기 시작이나 /eui tour lootguide로 다시 시작하세요.",
	["Engineering"] = "기계공학",
	["Enter from level"] = "입장 레벨",
	["enter from level %d"] = "레벨 %d부터 입장",
	["Enter saves, Shift+Enter new line, Esc closes."] = "Enter 저장, Shift+Enter 줄 바꿈, Esc 닫기.",
	["Enter saves, Shift+Enter starts a new line."] = "Enter 저장, Shift+Enter로 새 줄.",
	["Entered before the journal kept runs."] = "일지가 공략을 기록하기 전에 들어감.",
	["Entrance"] = "입구",
	["Entrance %s."] = "입구 %s.",
	["Entries"] = "항목",
	["Epic"] = "영웅",
	["Epic (purple)"] = "영웅 (보라색)",
	["Epic find"] = "영웅 발견",
	["Epic finds and the wishlist items you got."] = "영웅 발견과 얻은 위시리스트 아이템.",
	["Epic finds come from bosses deep in dungeons, later in your journey."] = "영웅 아이템은 던전 깊은 곳의 우두머리에게서 나오며, 여정 후반에 만납니다.",
	["Epic finds come from bosses. These dungeons fit your level:"] = "영웅 아이템은 우두머리에게서 나옵니다. 내 레벨에 맞는 던전:",
	["Equip a ranged weapon first."] = "먼저 원거리 무기를 착용하세요.",
	["Equipped %s"] = "%s 착용",
	["Eras"] = "시대",
	["Esc closes the window too."] = "Esc로도 창을 닫습니다.",
	["Essentials"] = "핵심",
	["estimate"] = "추정",
	["Estimates from fights against a target dummy with your own character sheet and public Classic combat rules. Set bonuses and item procs are not counted."] = "내 캐릭터 정보와 공개된 클래식 전투 규칙으로 훈련용 허수아비와 싸워 본 추정치입니다. 세트 효과와 아이템 발동 효과는 셈하지 않습니다.",
	["Everlook"] = "눈망루 마을",
	["Every attunement and key step by step. Its next steps show up in Next trips and on Today."] = "모든 입장 자격과 열쇠를 단계별로. 다음 단계는 다음 여정과 오늘에 나옵니다.",
	["Every attunement and key, step by step."] = "모든 입장 자격과 열쇠, 단계별로.",
	["Every best-in-slot item is already yours or on your wishlist."] = "모든 Best in Slot 아이템을 이미 가지고 있거나 위시리스트에 있습니다.",
	["Every craft per profession: what it makes, the skill it needs, the reagents you own and where the recipe comes from."] = "전문 기술별 모든 제작: 만드는 것, 필요한 숙련도, 가진 재료, 제조법 출처.",
	["Every dungeon and raid with its bosses, loot, drop chances and quests. Inside a dungeon the window opens on it."] = "모든 던전과 공격대의 우두머리, 전리품, 획득 확률, 퀘스트. 던전 안에서는 그 던전으로 창이 열립니다.",
	["Every dungeon and raid: bosses, drops with chances, quests and what is an upgrade for you."] = "모든 던전과 공격대: 우두머리, 확률이 붙은 전리품, 퀘스트, 나에게 상위 장비인 것.",
	["Every flight master you speak to adds a flight path. These zones fit your level:"] = "비행 조련사와 대화할 때마다 비행 경로가 늘어납니다. 내 레벨에 맞는 지역:",
	["Every idea for where to go next, with filters."] = "다음에 갈 곳에 대한 모든 아이디어, 필터 포함.",
	["Every idea, best first, with filters for dungeons, quests, attunements, and zones, for your group and the time you have. Hover a card to see every reason; Not now puts it away until your next level."] = "모든 아이디어를 좋은 것부터, 던전·퀘스트·입장 자격·지역 필터와 함께, 내 파티와 가진 시간에 맞춰 보여 줍니다. 카드에 마우스를 올리면 모든 이유가 나오고, 나중에는 다음 레벨까지 치워 둡니다.",
	["Every item, creature, quest and place in sortable tables with filters and a detail panel."] = "모든 아이템, 생물, 퀘스트, 장소를 정렬 가능한 표로, 필터와 세부 정보 패널 포함.",
	["Every item, mob, quest and vendor the loot data knows, with filters and sorting."] = "전리품 데이터에 있는 모든 아이템, 몹, 퀘스트, 상인을 필터와 정렬과 함께.",
	["Every keepsake, grouped by kind."] = "모든 기념품, 종류별로.",
	["Every kind of result."] = "모든 종류의 결과.",
	["Every level is behind you"] = "모든 레벨을 지났습니다",
	["Every level is behind you. The journal keeps writing down your runs, finds, and standings."] = "모든 레벨을 지났습니다. 일지는 계속 공략, 발견, 평판을 기록합니다.",
	["Every login"] = "접속할 때마다",
	["Every Loot Guide page is switched off. Turn pages on in /eui > Loot Guide."] = "Loot Guide의 모든 페이지가 꺼져 있습니다. /eui > Loot Guide에서 페이지를 켜세요.",
	["Every moment."] = "모든 순간.",
	["Every new standing"] = "새 평판마다",
	["Every new standing, or Honored and up only. Changing it on a preset turns it into Custom."] = "새 평판마다, 또는 우호적 이상만. 프리셋에서 바꾸면 사용자 설정이 됩니다.",
	["Every part and chapter of the Book. Click one to turn to it."] = "책의 모든 부와 장. 클릭하면 그곳으로 넘깁니다.",
	["Every PvP reward with its cost and the rank or standing it needs, plus a planner for the weeks to afford them."] = "모든 PvP 보상과 비용, 필요한 계급이나 평판, 그리고 살 수 있을 때까지의 주간 계획표.",
	["Every quest you handed in since the journal began, with where, when, and what it gave."] = "일지를 시작한 뒤 완료 보고한 모든 퀘스트, 장소·시간·보상 포함.",
	["Every quest you handed in, with where, when, who gave it, and who came along; your quest log; and the quests the game remembers from before."] = "완료 보고한 모든 퀘스트(장소, 시간, 의뢰인, 동행), 퀘스트 목록, 게임이 기억하는 이전 퀘스트.",
	["Every run the Instances module recorded."] = "인스턴스 모듈이 기록한 모든 공략.",
	["Every step for both sides and every class, also content the client does not list yet."] = "양 진영과 모든 직업의 모든 단계, 클라이언트가 아직 보여 주지 않는 콘텐츠도 포함.",
	["Every suggestion, best first."] = "모든 제안, 좋은 것부터.",
	["Every time"] = "매번",
	["Every way to get one item."] = "아이템 하나를 얻는 모든 방법.",
	["Every zone"] = "모든 지역",
	["Every zone you visited, with its corners, time, kills, and quests, and every dungeon with its runs."] = "방문한 모든 지역(구석, 시간, 처치, 퀘스트)과 모든 던전(공략).",
	["Every zone's quests: how many you have done, what is left and who gives it, with a Map button for each giver."] = "각 지역의 퀘스트: 몇 개를 완료했는지, 무엇이 남았는지, 누가 주는지, 퀘스트 제공자마다 지도 버튼과 함께.",
	["Everyone"] = "모두",
	["Everyone falls sometime. There is no need to chase this one."] = "누구나 한 번은 쓰러집니다. 이것까지 쫓을 필요는 없습니다.",
	["Everyone falls sometime. There is no need to chase this one; here is what fits you instead:"] = "누구나 한 번은 쓰러집니다. 이것까지 쫓을 필요는 없습니다. 대신 이것이 어울립니다:",
	["Everyone you grouped with."] = "함께 파티했던 모든 사람.",
	["Everything"] = "전부",
	["Everything is selected. Press Ctrl+C and share it. It holds your gear plans, spec and talents, not your name or realm."] = "전부 선택했습니다. Ctrl+C를 눌러 공유하세요. 장비 계획, 전문화, 특성이 들어 있으며 이름이나 서버는 없습니다.",
	["Everything is selected. Press Ctrl+C and share it. Others paste it into /eui import or the wishlist's Import."] = "전부 선택했습니다. Ctrl+C를 눌러 공유하세요. 다른 사람은 /eui import나 위시리스트의 가져오기에 붙여 넣습니다.",
	["Everything reached. Start a new one with New goal."] = "모두 달성했습니다. 새 목표로 새로 시작하세요.",
	["Everything you can get at your level is already as good as what you wear."] = "내 레벨에서 얻을 수 있는 모든 것이 이미 착용한 것만큼 좋습니다.",
	["Everything, rare (blue) finds too, long chapters, every chapter open and a taller tracker."] = "전부, 희귀(파란색) 발견까지, 긴 장, 모든 장 펼침, 더 큰 추적기.",
	["Exalted"] = "확고한 동맹",
	["Excavation Site"] = "발굴 현장",
	["Exclamation mark"] = "느낌표",
	["Experience"] = "경험치",
	["Experience and money next to each quest you handed in."] = "완료 보고한 퀘스트마다 경험치와 돈.",
	["Explored %s"] = "%s 탐험",
	["Export"] = "내보내기",
	["Export (share string)"] = "내보내기 (공유 문자열)",
	["Export a printable page"] = "인쇄용 페이지 내보내기",
	["Export as Markdown"] = "Markdown으로 내보내기",
	["Export as plain text"] = "일반 텍스트로 내보내기",
	["Export formats: %s."] = "내보내기 형식: %s.",
	["Faction"] = "진영",
	["Faction %d"] = "진영 %d",
	["Factions that count you as Honored or better."] = "나를 우호적 이상으로 보는 진영.",
	["falls"] = "쓰러짐",
	["Fanfare's \"Journal moment\" triggers play or show with each moment. While such a trigger, or a level-up or boss-kill trigger, has a sound, the moment plays none of its own, so you hear one sound."] = "Fanfare의 “일지 순간” 트리거는 순간마다 소리를 내거나 무언가를 보여 줍니다. 그런 트리거나 레벨 상승 또는 우두머리 처치 트리거에 소리가 있으면 순간은 자체 소리를 내지 않아 소리가 하나만 들립니다.",
	["Farmed for %s"] = "%s 동안 사냥",
	["Fast (8 ms a frame)"] = "빠름 (프레임당 8 ms)",
	["fastest"] = "가장 빠름",
	["Feet"] = "발",
	["Fellowship"] = "동료애",
	["Fewer"] = "적게",
	["Fiery Weapon"] = "불타는 무기",
	["Lifestealing"] = "생명력 흡수",
	["Fight"] = "전투",
	["Fighting"] = "전투 중",
	["Fights against a target dummy with the best items of your list (one-minute fights, out of combat). Progress shows here, in the datatext and as a toast when done."] = "목록의 최고 아이템으로 훈련용 허수아비와 싸웁니다 (1분 전투, 비전투 중). 진행 상황은 여기, 정보 문자, 끝날 때 알림으로 나옵니다.",
	["Fights against a target dummy with the best items of your list per slot: a quick pass, exact runs of the top picks, then the best set (one-minute fights, out of combat)."] = "칸마다 목록의 최고 아이템으로 훈련용 허수아비와 싸웁니다: 빠른 훑기, 상위 후보 정밀 실행, 그다음 최고 세트 (1분 전투, 비전투 중).",
	["Fights against a target dummy with this item instead of what you wear in its slot (about a second, out of combat). The result shows here, in the tooltip and as a toast."] = "그 칸에 착용 중인 것 대신 이 아이템으로 훈련용 허수아비와 싸웁니다 (약 1초, 비전투 중). 결과는 여기, 툴팁, 알림으로 나옵니다.",
	["Fights against a target dummy with your own character sheet. Slower, but counts how your talents and spells use each stat. Items not simulated yet keep the weights gain."] = "내 캐릭터 정보로 훈련용 허수아비와 싸웁니다. 느리지만 특성과 주문이 각 능력치를 어떻게 쓰는지 셉니다. 아직 시뮬레이션하지 않은 아이템은 가중치 이득을 유지합니다.",
	["Fights against a target dummy with your own character sheet: DPS numbers for your gear, Best in Slot and plan sets. /eui sim opens its window."] = "내 캐릭터 정보로 훈련용 허수아비와 싸웁니다: 장비, Best in Slot, 계획 세트의 DPS 수치. /eui sim으로 창을 엽니다.",
	["Fills an empty slot"] = "빈 칸을 채움",
	["Fills the set with the Best in Slot items (the simulated set in Simulator mode)."] = "세트를 Best in Slot 아이템으로 채웁니다 (시뮬레이터 모드에서는 시뮬레이션한 세트).",
