	["No known source. It may be new in WoW: Forever or come from something the data does not cover."] = "알려진 획득처가 없습니다. WoW: Forever에 새로 나왔거나 데이터에 없는 곳에서 얻는 것일 수 있습니다.",
	["No map art for this instance"] = "이 인스턴스의 지도 그림 없음",
