	["Notes on the world map"] = "세계 지도의 메모",
	["Notes remember where and when you wrote them. Press Enter in the box above to save one."] = "메모는 작성한 장소와 시간을 기억합니다. 위 입력창에서 Enter를 누르면 저장됩니다.",
	["Notes show as pins on the world map and minimap where you wrote them, with the Map Notes switch. Needs the Map Notes module."] = "지도 메모 스위치를 켜면 메모를 작성한 곳의 세계 지도와 미니맵에 표시합니다. 지도 메모 모듈이 필요합니다.",
	["Notes that remember where and when you wrote them, and reminders that show when you get somewhere."] = "작성한 장소와 시간을 기억하는 메모, 그리고 어딘가에 도착하면 나타나는 알림.",
