	["Nothing is lost: it merges with what My Adventure has, a backup is taken first, and Undo puts it back. Forever Journal's own data is only read, never changed."] = "잃는 것은 없습니다. 나의 모험의 내용과 합쳐지고, 먼저 백업을 만들며, 실행 취소로 되돌릴 수 있습니다. Forever Journal의 데이터는 읽기만 하고 절대 바꾸지 않습니다.",
