	["No rewards match these filters."] = "이 필터에 맞는 보상이 없습니다.",
	["Nothing new to report yet. The Journal notes the quests, dungeons, and zones the data does not know as you meet them."] = "아직 보고할 새 내용이 없습니다. 일지는 데이터가 모르는 퀘스트, 던전, 지역을 만나는 대로 기록합니다.",
