	["Numbered boss markers from the loot data on the dungeon map window. They never show where you are."] = "던전 지도 창에 전리품 데이터의 번호 붙은 우두머리 표시. 내 위치는 절대 표시하지 않습니다.",
	["Numbered markers are the bosses, from the Classic data. Click one for its loot; click it again to close the list."] = "번호 표시는 Classic 데이터의 우두머리입니다. 클릭하면 전리품을, 다시 클릭하면 목록을 닫습니다.",
