	["On a level-up the moment links to the dungeons, quests, spells and attunement steps that just opened."] = "레벨이 오르면 그 순간에 막 열린 던전, 퀘스트, 주문, 입장 자격 단계를 연결합니다.",
	["On a quest link: when you took it or handed it in, at what level and where, and whether it is part of your next trip."] = "퀘스트 링크 위에서: 언제 받거나 완료했는지, 몇 레벨에 어디서였는지, 다음 여행에 포함되는지.",
	["On an item that is a step of an attunement: which one, whether you have it, and with Shift the next step."] = "입장 자격 단계인 아이템 위에서: 어떤 자격인지, 가지고 있는지, Shift를 누르면 다음 단계.",
	["On an item:"] = "아이템 위에서:",
	["On an item: when and where your journal saw you find it or put it on, and at what level."] = "아이템 위에서: 일지가 언제 어디서 당신이 그것을 찾거나 착용하는 것을 보았는지, 몇 레벨이었는지.",
	["on the quest"] = "퀘스트 중",
