	["One kind, like Mottled Worg. Counts each one that gives you experience."] = "게임 속 이름의 생물 한 종류. 경험치를 주는 개체를 모두 셉니다.",
	["One line for the tooltip."] = "툴팁에 한 줄.",
	["One line with the next thing that matters: a ready hand-in, trip prep or the next attunement step."] = "다음으로 중요한 일 한 줄: 완료 보고할 퀘스트, 여행 준비 또는 다음 입장 자격 단계.",
	["One more point is worth"] = "1포인트 더의 가치",
	["one of these"] = "이 중 하나",
	["One of these is enough"] = "이 중 하나면 충분",
	["One of your professions."] = "내 전문 기술 중 하나.",
	["One particular dungeon, once or many times."] = "특정 던전 하나, 한 번 또는 여러 번.",
	["one per slot, biggest gain first"] = "칸마다 하나, 향상이 큰 순",
	["One quest, or the last quest of a chain you are working on."] = "퀘스트 하나 또는 진행 중인 퀘스트 줄기의 마지막 퀘스트.",
	["One step per row and finished attunements hidden: easy to read at a small window scale."] = "줄마다 한 단계, 완료한 입장 자격 숨김: 창 크기가 작을 때 읽기 쉬움.",
	["One step per row, in order. Easier to read at a small window scale."] = "줄마다 한 단계, 순서대로. 창 크기가 작을 때 읽기 쉬움.",
	["One summary when you leave"] = "떠날 때 요약 한 번",
	["one target only"] = "단일 대상만",
	["One-hand"] = "한손",
	["Online"] = "접속 중",
	["Only %s"] = "%s만",
	["Only %s."] = "%s만.",
	["only below 20 % health"] = "생명력 20 % 미만에서만",
	["Only by hand"] = "직접 할 때만",
	["Only crafts learned in this skill range."] = "이 숙련도 범위에서 배우는 제조법만.",
	["Only creatures that drop at least one upgrade for you."] = "업그레이드를 하나 이상 주는 생물만.",
	["Only dungeons and raids."] = "던전과 공격대만.",
	["Only guild members who are online now."] = "지금 접속 중인 길드원만.",
	["Only items in your bags, bank or on your other characters (from Bags)."] = "가방, 은행 또는 다른 캐릭터에 있는 아이템만(가방 기준).",
	["Only items your class, race and professions can use (any level)."] = "내 직업, 종족, 전문 기술로 쓸 수 있는 아이템만(모든 레벨).",
	["Only members at level 60."] = "60레벨 길드원만.",
	["Only members who have not finished every attunement in the columns."] = "열에 있는 입장 자격을 모두 마치지 않은 길드원만.",
	["only on a dying target"] = "죽어 가는 대상에게만",
	["Only places whose level range fits you or is close."] = "레벨 범위가 맞거나 가까운 장소만.",
	["Only quests for your side, race, class and professions."] = "내 진영, 종족, 직업, 전문 기술에 맞는 퀘스트만.",
