	["Open a dungeon in the Journal and press Dungeon map: the floors with numbered boss markers. Entrance pins the way in on your world map."] = "일지에서 던전을 열고 던전 지도를 누르세요: 번호 붙은 우두머리 표시가 있는 층. 입구는 세계 지도에 들어가는 길을 표시합니다.",
	["Open a quest or a creature from Search or an item page."] = "검색이나 아이템 페이지에서 퀘스트 또는 생물을 여세요.",
