	["Opens a card that compares the item with what you wear, its source and your plans."] = "아이템을 착용 중인 것, 획득처, 계획과 비교하는 카드를 엽니다.",
	["Opens a copy box with the Forever quests you took, to send to EldoUI's authors so the dungeon can get a full chain."] = "받은 Forever 퀘스트가 담긴 복사 상자를 엽니다. EldoUI 제작자에게 보내면 던전에 완전한 퀘스트 줄기가 생깁니다.",
	["Opens a copy box with the list, to send to EldoUI's authors so the dungeon can get a full chain."] = "목록이 담긴 복사 상자를 엽니다. EldoUI 제작자에게 보내면 던전에 완전한 퀘스트 줄기가 생깁니다.",
	["Opens EldoUI's keybind mode. My Adventure's keys (open or close it, quick note, the tracker, and Next trips) are also under Options > Keybindings > AddOns > EldoUI."] = "EldoUI 단축키 모드를 엽니다. 나의 모험의 키(열기/닫기, 빠른 메모, 추적기, 다음 여행)는 설정 > 단축키 > 애드온 > EldoUI에도 있습니다.",
	["Opens its page in the Journal."] = "일지에서 해당 페이지를 엽니다.",
