	["Opens the Open World tab: zones, rares and world drops."] = "야외 세계 탭을 엽니다: 지역, 희귀 몹, 월드 드롭.",
	["Opens the place in the Journal."] = "일지에서 장소를 엽니다.",
	["Opens the quest in the Loot Guide: where to get it, what it needs, and its rewards."] = "Loot Guide에서 퀘스트를 엽니다: 받는 곳, 필요한 것, 보상.",
	["Opens the spells your class trainer teaches that you don't know yet."] = "직업 전문가가 가르치는 주문 중 아직 배우지 않은 주문을 엽니다.",
