	["Outdated: your gear, talents, level or the fight settings changed since this run. Press Sim to run it again."] = "오래됨: 이 계산 뒤로 장비, 특성, 레벨 또는 전투 설정이 바뀌었습니다. 다시 하려면 Sim을 누르세요.",
