	["Party %d"] = "파티 %d",
	["Pass"] = "포기",
	["Paste a journal backup code starting with !EUJ1!, FJ2: or FJ1:. You see what it holds before anything changes."] = "!EUJ1!, FJ2: 또는 FJ1:로 시작하는 일지 백업 코드를 붙여 넣으세요. 변경하기 전에 내용을 먼저 확인합니다.",
	["Paste a journal code"] = "일지 코드 붙여 넣기",
	["Paste a wishlist string (Ctrl+V) and click Save."] = "위시리스트 문자열을 붙여 넣고(Ctrl+V) 저장을 클릭하세요.",
	["Paste it into a journal-data issue. It changes nothing in your game."] = "journal-data 이슈에 붙여 넣으세요. 게임에서는 아무것도 바뀌지 않습니다.",
	["paused for combat"] = "전투로 일시 정지",
	["Paused for combat. The run goes on when combat ends."] = "전투로 일시 정지했습니다. 전투가 끝나면 계속합니다.",
	["People"] = "사람",
	["People you grouped with long enough for the journal to remember."] = "일지가 기억할 만큼 오래 함께 파티한 사람.",
	["People you grouped with long enough for the journal to remember. Names show while Name companions is on."] = "일지가 기억할 만큼 오래 함께 파티한 사람. 동료 이름 넣기가 켜져 있으면 이름이 표시됩니다.",
	["Pet"] = "소환수",
	["pet cooldowns are not modeled"] = "소환수 재사용 대기시간은 계산하지 않음",
	["Pick a backup, then Merge (keeps everything since) or Replace (exactly as it was). Your journal is backed up first."] = "백업을 고른 뒤 합치기(그 뒤의 내용 유지) 또는 바꾸기(정확히 그때 상태)를 고르세요. 일지는 먼저 백업됩니다.",
	["Pick a craft to see its reagents and where the recipe comes from."] = "제조법을 고르면 재료와 제조법을 얻는 곳을 봅니다.",
	["Pick a craft: its reagents with what you own and where the recipe comes from, with Map buttons."] = "제조법을 고르세요: 보유한 재료와 제조법을 얻는 곳, 지도 버튼과 함께.",
	["Pick a faction on the left."] = "왼쪽에서 진영을 고르세요.",
	["Pick a level above the one you have."] = "현재보다 높은 레벨을 고르세요.",
	["Pick a quest on the left to see its chain, objectives and rewards."] = "왼쪽에서 퀘스트를 고르면 줄기, 임무, 보상을 봅니다.",
	["Pick a row to see it here."] = "줄을 고르면 여기에 표시합니다.",
	["Pick a zone"] = "지역 선택",
	["Pick an attunement from the list, or type its name."] = "목록에서 입장 자격을 고르거나 이름을 입력하세요.",
	["Pick an item from your wishlist."] = "위시리스트에서 아이템을 고르세요.",
	["pick one and open it in the Loot Guide"] = "하나를 골라 Loot Guide에서 열기",
	["Pick the list the stars add to, show other lists, make, rename, share or delete lists."] = "별표가 추가될 목록 선택, 다른 목록 표시, 목록 만들기·이름 바꾸기·공유·삭제.",
	["Pick the target dummy's level and the fight length. Bosses are three levels above you."] = "훈련용 허수아비의 레벨과 전투 시간을 고르세요. 우두머리는 나보다 3레벨 높습니다.",
	["Pick up a quest and it shows here until you hand it in."] = "퀘스트를 받으면 완료할 때까지 여기에 표시됩니다.",
	["Pick up its quests before you go."] = "가기 전에 퀘스트를 받으세요.",
	["Pick up: %s"] = "받기: %s",
	["Pick what you want to work towards."] = "이루고 싶은 것을 고르세요.",
	["Picked up %s · %s ago"] = "%s에 받음 · %s 전",
	["Picked up %s · handed in %s · took %s"] = "%s에 받음 · %s에 완료 · %s 걸림",
	["Picked up in %s"] = "%s에서 받음",
	["Picks new wording for the whole Book. The facts don't change."] = "책 전체의 문구를 새로 고릅니다. 사실은 바뀌지 않습니다.",
	["Picks new wording for the whole story. The facts don't change."] = "이야기 전체의 문구를 새로 고릅니다. 사실은 바뀌지 않습니다.",
	["Pin"] = "고정",
	["Pin look"] = "표시 모양",
	["Pin new notes to the Journey"] = "새 메모를 여정에 고정",
	["Pin size"] = "표시 크기",
	["Pin to Journey"] = "여정에 고정",
	["Pinned"] = "고정됨",
	["pinned"] = "고정됨",
	["Pinned notes"] = "고정한 메모",
	["Pins at dungeon and raid entrances on the world and zone maps, with the level range and your upgrades inside. Where the game draws its own entrance pin, ours steps aside, so no entrance shows twice."] = "세계 지도와 지역 지도의 던전 및 공격대 입구 표시, 레벨 범위와 안에 있는 업그레이드 포함. 게임이 자체 입구 표시를 그리는 곳에서는 입구가 두 번 보이지 않도록 이 표시가 숨겨집니다.",
	["Pins for the givers of quests you can pick up now."] = "지금 받을 수 있는 퀘스트의 제공자 표시.",
	["Pins the biggest of %d camps on your map. Click again for the next one; after the last the pin goes away."] = { other = "%d개 야영지 중 가장 큰 곳을 지도에 표시합니다. 다시 클릭하면 다음 곳, 마지막 다음에는 표시가 사라집니다." },
	["Pins the dungeon's entrance on your map."] = "던전 입구를 지도에 표시합니다.",
	["Pins the entrance in %s on your map and turns on the arrow."] = "%s의 입구를 지도에 표시하고 화살표를 켭니다.",
	["Pins the entrance on your map and opens the map there (out of combat)."] = "입구를 지도에 표시하고 그곳의 지도를 엽니다(비전투 중).",
	["Pins the entrance on your map."] = "입구를 지도에 표시합니다.",
	["Pins the instance entrance on your map and turns on the arrow."] = "인스턴스 입구를 지도에 표시하고 화살표를 켭니다.",
	["Pins the instance entrance on your map, turns on the arrow and opens the map there (out of combat)."] = "인스턴스 입구를 지도에 표시하고 화살표를 켠 뒤 그곳의 지도를 엽니다(비전투 중).",
	["Pins the place on your map and turns on the arrow."] = "장소를 지도에 표시하고 화살표를 켭니다.",
	["Pins the place on your map and turns on the arrow. Click again to take the pin away."] = "장소를 지도에 표시하고 화살표를 켭니다. 다시 클릭하면 표시를 지웁니다.",
	["Place"] = "장소",
	["Places"] = "장소",
	["Places the boss markers by where the creatures stand in the Classic data, on a plain grid. Approximate: walls and floors are not drawn."] = "Classic 데이터의 생물 위치에 맞춰 단순한 격자 위에 우두머리 표시를 놓습니다. 대략적: 벽과 바닥은 그리지 않습니다.",
	["Plan"] = "계획",
	["Plan pieces to see the total and how many weeks of your recent honor each one takes."] = "부위를 계획하면 합계와 각 부위에 최근 명예로 몇 주가 걸리는지 봅니다.",
	["Plan set"] = "계획 세트",
	["Plan set %d"] = "계획 세트 %d",
	["Plan the trip"] = "여행 계획",
	["Planned"] = "계획됨",
	["Planner"] = "플래너",
	["Plate"] = "판금",
	["Play when game effects are muted"] = "게임 효과음이 꺼져 있을 때도 재생",
	["played"] = "플레이",
	["Played for %s"] = "%s 동안 플레이",
	["Player notes"] = "플레이어 메모",
	["Plays moment sounds on the Master channel."] = "순간 효과음을 주 채널로 재생합니다.",
	["Plays with the toast for a finished attunement. Step toasts are silent."] = "입장 자격 완료 알림과 함께 재생됩니다. 단계 알림은 소리가 없습니다.",
	["Plays with this kind of moment. None: the card stays quiet."] = "이 종류의 순간에 재생됩니다. 없음: 카드는 조용합니다.",
	["Poison"] = "독",
	["Poor"] = "하급",
	["Poor (gray)"] = "하급(회색)",
	["Posts one line in guild chat."] = "길드 대화에 한 줄을 씁니다.",
	["Press %s to take a screenshot. Click or press Esc to close."] = "스크린샷을 찍으려면 %s 키를 누르세요. 닫으려면 클릭하거나 Esc를 누르세요.",
	["Press Ctrl+C to copy it, save it as a .html file and open it in a browser. Print it to PDF for a keepsake."] = "Ctrl+C로 복사하고 .html 파일로 저장해 브라우저에서 여세요. 기념으로 PDF로 인쇄하세요.",
	["Press Ctrl+C to copy it, then paste it anywhere."] = "Ctrl+C로 복사한 뒤 아무 곳에나 붙여 넣으세요.",
	["Press Ctrl+C to copy it, then paste it into any Markdown editor or note app."] = "Ctrl+C로 복사한 뒤 Markdown 편집기나 메모 앱에 붙여 넣으세요.",
	["Press Ctrl+C to copy the code. Use \"Paste a journal code\" on this PC or another to restore the journal. Nothing is sent anywhere."] = "Ctrl+C로 코드를 복사하세요. 이 PC나 다른 PC에서 \"일지 코드 붙여 넣기\"를 사용하면 일지를 복원합니다. 어디로도 보내지 않습니다.",
	["Press Ctrl+C to copy. Nothing is sent anywhere: paste it where you like."] = "Ctrl+C로 복사하세요. 어디로도 보내지 않습니다. 원하는 곳에 붙여 넣으세요.",
	["Press Ctrl+C to copy. Paste it back in with Paste a journal code, on this PC or another. Nothing is sent anywhere."] = "Ctrl+C로 복사하세요. 이 PC나 다른 PC에서 일지 코드 붙여 넣기로 다시 넣을 수 있습니다. 어디로도 보내지 않습니다.",
	["Press Sim to compare the checked sets in the same fights."] = "Sim을 누르면 체크한 세트를 같은 전투에서 비교합니다.",
	["Press Sim to read your character and fight a target dummy 120 times. It takes a few seconds and runs out of combat."] = "Sim을 누르면 캐릭터를 읽고 훈련용 허수아비와 120번 싸웁니다. 몇 초 걸리며 비전투 중에 진행합니다.",
	["Previews a code starting with !EUJ1!, FJ2: or FJ1:. A full backup can be merged or used to replace your journal. Recent changes are merged."] = "!EUJ1!, FJ2: 또는 FJ1:로 시작하는 코드의 내용을 미리 봅니다. 전체 백업은 일지와 합치거나 일지를 바꾸는 데 사용할 수 있습니다. 최근 변경 사항은 일지와 합칩니다.",
	["Previous pages"] = "이전 페이지",
	["Prints where the loot data comes from (same as /lg data)."] = "전리품 데이터의 출처를 출력합니다(/lg data와 같음).",
	["Prints where the loot data comes from, its version and size (same as /lg data)."] = "전리품 데이터의 출처, 버전, 크기를 출력합니다(/lg data와 같음).",
	["profession"] = "전문 기술",
	["Profession mastered"] = "전문 기술 숙련",
	["Profession needed"] = "필요한 전문 기술",
	["Protection: Shield Slam and Sunder Armor"] = "방어: 방패 밀쳐내기와 방어구 가르기",
	["Providers:"] = "제공처:",
	["Put away (%d)"] = "치워 둠 (%d)",
	["Put away until your next break."] = "다음 휴식까지 치워 둠.",
	["Put away until your next level or for 24 hours."] = "다음 레벨까지 또는 24시간 동안 치워 둠.",
	["Put in %s"] = "%s에 넣기",
	["Put in chat"] = "대화창에 넣기",
	["put it in the chat box"] = "대화 입력창에 넣기",
	["Put on %s"] = "착용: %s",
	["Put on %s in %s"] = "착용: %s, %s",
	["Puts a group line into the chat box. Nothing is sent until you press Enter."] = "파티 모집 문구를 대화 입력창에 넣습니다. Enter를 누르기 전에는 보내지 않습니다.",
	["Puts every journal the last import touched back as it was before, and its settings too."] = "마지막 가져오기가 바꾼 모든 일지를 설정까지 이전 상태로 되돌립니다.",
	["Puts every piece you do not have on your active wishlist."] = "없는 부위를 모두 활성 위시리스트에 넣습니다.",
	["Puts its quests that are already in your log on the objective tracker. Nothing is accepted for you."] = "이미 퀘스트 목록에 있는 해당 퀘스트를 목표 추적기에 올립니다. 대신 수락하지 않습니다.",
	["Puts one line about your character in the chat box. You read it and press Enter to send it."] = "캐릭터 소개 한 줄을 대화 입력창에 넣습니다. 읽어 보고 Enter를 눌러 보내세요.",
	["Puts the item in this plan set on the Best in Slot page, or takes it out. Plan sets are plans, not equipment sets."] = "Best in Slot 페이지의 이 계획 세트에 아이템을 넣거나 뺍니다. 계획 세트는 계획일 뿐 장비 구성이 아닙니다.",
	["Puts the item link into the chat line you are typing in."] = "입력 중인 대화줄에 아이템 링크를 넣습니다.",
	["Puts the window back at the top of the screen at normal size."] = "창을 기본 크기로 화면 위쪽에 되돌립니다.",
	["Puts this card away until your next break."] = "이 카드를 다음 휴식까지 치워 둡니다.",
	["Puts this card away until your next level or for 24 hours."] = "이 카드를 다음 레벨까지 또는 24시간 동안 치워 둡니다.",
	["Puts this card away."] = "이 카드를 치워 둡니다.",
	["Puts this goal back on the page."] = "이 목표를 페이지에 되돌립니다.",
	["Puts this note back on the page."] = "이 메모를 페이지에 되돌립니다.",
	["Puts this quest back on the page."] = "이 퀘스트를 페이지에 되돌립니다.",
	["PvP"] = "PvP",
	["PvP armor"] = "PvP 방어구",
	["PvP class sets"] = "PvP 직업 세트",
	["PvP is off in your filter"] = "필터에서 PvP가 꺼져 있음",
	["PvP rewards come from EldoUI_LootData. Install it next to EldoUI to list them."] = "PvP 보상은 EldoUI_LootData에서 가져옵니다. 목록을 보려면 EldoUI 옆에 설치하세요.",
	["PvP sets"] = "PvP 세트",
	["PvP weapons"] = "PvP 무기",
	["PvP: honor per week"] = "PvP: 주간 명예",
	["Quality"] = "품질",
	["Quartermasters"] = "병참장교",
	["Quest"] = "퀘스트",
	["quest"] = "퀘스트",
	["Quest %d"] = "퀘스트 %d",
	["Quest chain"] = "퀘스트 줄기",
	["Quest choice: %s"] = "선택 보상: %s",
	["Quest count in the zone tooltip"] = "지역 툴팁의 퀘스트 수",
	["Quest details"] = "퀘스트 세부 정보",
	["Quest giver"] = "퀘스트 제공자",
	["Quest givers"] = "퀘스트 제공자",
	["Quest givers on the map"] = "지도의 퀘스트 제공자",
	["Quest icons"] = "퀘스트 아이콘",
	["Quest icons on bronze, to match the WoW Forever art style."] = "청동 위의 퀘스트 아이콘, WoW Forever 아트 스타일에 맞춤.",
	["Quest icons on the map for quests you can take now; everything listed."] = "지금 받을 수 있는 퀘스트를 위한 지도 위 퀘스트 아이콘; 모두 목록에 표시.",
	["Quest item"] = "퀘스트 아이템",
	["Quest level %d"] = "퀘스트 레벨 %d",
	["Quest reward"] = "퀘스트 보상",
	["Quest reward: %s"] = "퀘스트 보상: %s",
	["Quest rewards"] = "퀘스트 보상",
	["Quest rewards, dungeon and raid drops and crafted gear."] = "퀘스트 보상, 던전과 공격대 전리품, 제작 장비.",
	["Quest Starter Drops"] = "퀘스트 시작 아이템",
	["quest you have done or can't take"] = "이미 했거나 받을 수 없는 퀘스트",
	["Quest, level %d"] = "퀘스트, 레벨 %d",
	["Quest: %s"] = "퀘스트: %s",
	["Questions, ideas or a wrong drop? Copy this address (Ctrl+C) and open it in your browser."] = "질문, 아이디어 또는 잘못된 전리품이 있나요? 이 주소를 복사(Ctrl+C)해 브라우저에서 여세요.",
	["Quests"] = "퀘스트",
	["quests"] = "퀘스트",
	["Quests %s"] = "%s 퀘스트",
	["Quests above your level"] = "내 레벨보다 높은 퀘스트",
	["Quests above your level by more than this are not suggested."] = "내 레벨보다 이 값을 넘게 높은 퀘스트는 추천하지 않습니다.",
	["Quests and companions"] = "퀘스트와 동료",
	["Quests are quicker with company. These fit your level:"] = "퀘스트는 함께하면 더 빠릅니다. 내 레벨에 맞는 퀘스트:",
	["quests completed"] = "완료한 퀘스트",
	["Quests for you"] = "추천 퀘스트",
	["Quests grouped by"] = "퀘스트 묶는 기준",
	["quests handed in"] = "완료 보고한 퀘스트",
	["Quests handed in"] = "완료 보고한 퀘스트",
	["Quests handed in here"] = "여기서 완료 보고한 퀘스트",
	["Quests that left your log without a hand-in: abandoned, failed, or removed by the game. With where and when you took each one."] = "완료 보고 없이 목록에서 사라진 퀘스트: 포기, 실패 또는 게임이 제거한 것. 각각 언제 어디서 받았는지 포함.",
	["Quests that need a prerequisite"] = "선행 퀘스트가 필요한 퀘스트",
	["Quests that reward the item, need it or start from it."] = "이 아이템을 보상으로 주거나, 필요로 하거나, 이 아이템으로 시작하는 퀘스트.",
	["Quests that reward the item, need it, or start from it."] = "이 아이템을 보상으로 주거나, 필요로 하거나, 이 아이템으로 시작하는 퀘스트.",
	["Quests the game remembers you finished before the journal began. The game does not say when."] = "일지를 시작하기 전에 완료했다고 게임이 기억하는 퀘스트. 게임은 날짜를 알려 주지 않습니다.",
	["Quests to hand in, attunements under way, your goals, reminders, and mail that runs out soon."] = "완료 보고할 퀘스트, 진행 중인 입장 자격, 목표, 알림, 곧 만료되는 우편.",
	["Quests to hand in, quests in your log by zone, and quest chains to go on with."] = "완료 보고할 퀘스트, 지역별 퀘스트 목록, 이어 갈 퀘스트 줄기.",
	["quests together"] = "함께 한 퀘스트",
	["Quests together"] = "함께 한 퀘스트",
	["Quests you can take now"] = "지금 받을 수 있는 퀘스트",
	["Quests you handed in at these levels."] = "이 레벨에서 완료 보고한 퀘스트.",
	["Quests you have taken for it"] = "이것을 위해 받은 퀘스트",
	["Quests, crafted and other"] = "퀘스트, 제작 및 기타",
	["Quests, dungeons, crafted, vendors and reputation; no rares, world drops or PvP; every drop chance; every armor kind you wear."] = "퀘스트, 던전, 제작, 상인, 평판; 희귀 몹, 월드 드롭, PvP 제외; 모든 획득 확률; 착용하는 모든 방어구 종류.",
	["Quick note"] = "빠른 메모",
	["Quiet"] = "조용히",
	["Raid"] = "공격대",
	["Raid %d"] = "공격대 %d",
	["Raid attunement"] = "공격대 입장 자격",
	["Raid boss down"] = "공격대 우두머리 처치",
	["Raider"] = "공격대원",
	["Raids"] = "공격대",
	["Raids and the world bosses."] = "공격대와 월드 우두머리.",
	["Raids join the suggestions (the Include raids setting of My Adventure)."] = "공격대가 추천에 포함됩니다(나의 모험의 공격대 포함 설정).",
