	["Shift into Cat Form first, so the simulator can read your cat's attack power."] = "먼저 표범 변신을 하세요. 그래야 시뮬레이터가 표범의 전투력을 읽을 수 있습니다.",
	["Shift-click"] = "Shift+클릭",
