	["Shift-click the Loot Guide button or datatext for the page you left, even inside a dungeon."] = "Loot Guide 버튼이나 정보 문자를 Shift+클릭하면 던전 안에서도 마지막 페이지를 엽니다.",
	["Shift-click the quest into the box, or pick one from your quest log."] = "퀘스트를 Shift+클릭해 입력창에 넣거나 퀘스트 목록에서 고르세요.",
