	["Show steps for"] = "단계 보기 대상",
	["Show the %s page in the Loot Guide window."] = "Loot Guide 창에서 %s 페이지를 보여 줍니다.",
	["Show the %s page in the Loot Guide window. Hiding it also hides gain marks in lists and plan sets in tooltips."] = "Loot Guide 창에서 %s 페이지를 보여 줍니다. 숨기면 목록의 이득 표시와 툴팁의 계획 세트도 숨겨집니다.",
	["Show the %s page in the Loot Guide window. Hiding it also hides the wishlist stars and tooltip line."] = "Loot Guide 창에서 %s 페이지를 보여 줍니다. 숨기면 위시리스트 별과 툴팁 줄도 숨겨집니다.",
	["Show the quests in progress"] = "진행 중인 퀘스트 보기",
	["Show the story"] = "이야기 보기",
	["Show them as they happen, or hold them and show one summary when you leave."] = "일어날 때마다 보여 주거나, 모아 두었다가 떠날 때 요약 하나로 보여 줍니다.",
	["Show what this token buys"] = "이 토큰으로 살 수 있는 것 보기",
	["Showing the first %d items. Type more to narrow it down."] = "처음 %d개 아이템을 표시합니다. 더 입력해서 좁히세요.",
	["Shown here and used for upgrades when Rate items by is Simulator. Estimates: set bonuses and item procs are not counted."] = "아이템 평가 기준이 시뮬레이터일 때 여기에 표시되고 상위 장비 판단에 쓰입니다. 추정치: 세트 효과와 아이템 발동 효과는 계산하지 않습니다.",
	["Shows a level moment the way it looks with your settings."] = "현재 설정으로 레벨 순간이 어떻게 보이는지 보여 줍니다.",
	["Shows a sample alert with your settings."] = "현재 설정으로 예시 알림을 보여 줍니다.",
	["Shows a sample toast with your settings."] = "현재 설정으로 예시 알림 창을 보여 줍니다.",
	["Shows an item tooltip with the Loot Guide lines, so you can see your settings."] = "Loot Guide 줄이 들어간 아이템 툴팁을 보여 주어 설정을 확인할 수 있습니다.",
	["Shows both factions, every class and content the game does not list yet."] = "두 진영, 모든 직업, 그리고 게임에 아직 없는 콘텐츠를 보여 줍니다.",
	["Shows every drop of this rare."] = "이 희귀 몹의 모든 전리품을 보여 줍니다.",
	["Shows every kind."] = "모든 종류를 보여 줍니다.",
	["Shows every piece on your character in the dressing room."] = "캐릭터가 모든 부위를 착용한 모습을 미리보기 창에서 보여 줍니다.",
	["Shows every place again."] = "모든 장소를 다시 보여 줍니다.",
	["Shows gain marks, plan sets and upgrades again."] = "이득 표시, 계획 세트와 상위 장비를 다시 보여 줍니다.",
	["Shows how much the item would gain you beside each loot roll. Advice only: you always roll yourself."] = "각 전리품 주사위 굴림 옆에 아이템으로 얻을 이득을 보여 줍니다. 조언일 뿐이며 주사위는 항상 직접 굴립니다.",
	["Shows on the Attunements tab how many attunements, steps and quests are loaded and the data version."] = "입장 자격 탭에 불러온 입장 자격, 단계, 퀘스트 수와 데이터 버전을 보여 줍니다.",
	["Shows only instances within the level window of yours (Loot Guide settings)."] = "내 레벨 범위 안의 인스턴스만 보여 줍니다 (Loot Guide 설정).",
	["Shows only items that beat what you wear, rated by the shared item engine."] = "공용 아이템 엔진으로 평가해서 착용 중인 것보다 나은 아이템만 보여 줍니다.",
	["Shows only rares and creatures that drop an upgrade for you."] = "내게 상위 장비를 주는 희귀 몹과 몹만 보여 줍니다.",
	["Shows only rewards that beat what you wear."] = "착용 중인 것보다 나은 보상만 보여 줍니다.",
	["Shows only this armor kind. Click again for all."] = "이 방어구 종류만 보여 줍니다. 다시 클릭하면 모두 보여 줍니다.",
	["Shows that attunement."] = "해당 입장 자격을 보여 줍니다.",
	["Shows the attunements before these as columns."] = "이 앞의 입장 자격을 열로 보여 줍니다.",
	["Shows the item on your character in the dressing room."] = "캐릭터가 아이템을 착용한 모습을 미리보기 창에서 보여 줍니다.",
	["Shows the next attunements as columns."] = "다음 입장 자격을 열로 보여 줍니다.",
	["Shows the note on your Journey, under the level you wrote it at."] = "여정에서 메모를 작성한 레벨 아래에 메모를 보여 줍니다.",
