	["Shows the quest in the Quests table."] = "이 퀘스트를 퀘스트 표에 보여 줍니다.",
	["Shows the quests for this place in the Quests table."] = "이 장소의 퀘스트를 퀘스트 표에 보여 줍니다.",
	["Shows the three best drops only."] = "가장 좋은 전리품 세 개만 보여 줍니다.",
	["Shows the zone's creatures in the Mobs table."] = "이 지역의 몹을 몹 표에 보여 줍니다.",
	["Shows this floor. Your pick is remembered for this dungeon."] = "이 층을 보여 줍니다. 선택은 이 던전에 대해 기억됩니다.",
