	["Shows what the tab has loaded, here in the window."] = "탭이 불러온 내용을 이 창에서 보여 줍니다.",
	["Shows what was noted as one block to copy into a journal-data issue. Nothing is sent from the game."] = "기록한 내용을 journal-data 이슈에 복사할 한 덩어리로 보여 줍니다. 게임에서는 아무것도 보내지 않습니다.",
