	["Spec, armor, sources, lowest drop chance and stat priority: what counts as your gear everywhere in EldoUI."] = "전문화, 방어구, 획득처, 가장 낮은 획득 확률과 능력치 우선순위: EldoUI 어디서나 내 장비로 치는 기준입니다.",
