	["Standings"] = "평판 등급",
	["Star items anywhere to wish for them. You get an alert when one drops, is in a roll or in the dungeon you enter."] = "어디서든 아이템에 별표를 달아 원하는 아이템으로 삼으세요. 그 아이템이 나오거나, 주사위 굴림에 있거나, 들어간 던전에 있으면 알림을 받습니다.",
	["Star items in the Journal, Search or any list and the places to get them show here."] = "일지, 검색 또는 어떤 목록에서든 아이템에 별표를 달면 그 아이템과 얻을 장소가 여기에 나옵니다.",
	["Start"] = "시작",
	["Start and finish"] = "시작과 완료",
	["Start tour"] = "안내 시작",
	["Started without a quest giver"] = "퀘스트 제공자 없이 시작함",
	["Starts"] = "시작",
	["Starts at %s"] = "시작 위치: %s",
	["Stat priority"] = "능력치 우선순위",
	["Stat priority: drag a stat to change the order. Default order takes your change back."] = "능력치 우선순위: 능력치를 드래그해 순서를 바꾸세요. 기본 순서를 누르면 변경을 되돌립니다.",
	["Stats"] = "능력치",
	["Status"] = "상태",
	["Status: ? ready, ! open, x locked, - too low or not for you, v done."] = "상태: ? 완료 가능, ! 진행 가능, x 잠김, - 레벨이 낮거나 해당 없음, v 완료.",
	["step %d of %d"] = "%d/%d단계",
	["step %d of %d in the zone"] = "지역 안에서 %d / %d 단계",
	["Step %d of %d: %s"] = "%d/%d단계: %s",
	["Step %d: %s"] = "%d단계: %s",
	["Step alerts"] = "단계 알림",
	["Step done"] = "단계 완료",
	["Step list"] = "단계 목록",
	["Step quests the game has no title for (removed or renumbered on WoW: Forever). Copy it (Ctrl+C) and send it to EldoUI's authors."] = "게임에 제목이 없는 단계 퀘스트입니다 (WoW: Forever에서 삭제되었거나 번호가 바뀜). 복사해서(Ctrl+C) EldoUI 제작자에게 보내 주세요.",
	["Steps"] = "단계",
	["Steps the number down. Shift-click steps ten times as far."] = "숫자를 한 단계 내립니다. Shift+클릭하면 열 배씩 내립니다.",
	["Steps the number up. Shift-click steps ten times as far."] = "숫자를 한 단계 올립니다. Shift+클릭하면 열 배씩 올립니다.",
	["Still ahead."] = "아직 남았습니다.",
	["Still open: %s."] = "아직 남음: %s.",
	["Still to do"] = "아직 할 일",
	["Stop"] = "중지",
	["Stops the run. Results saved so far stay."] = "실행을 멈춥니다. 지금까지 저장된 결과는 남습니다.",
	["Stops the simulator run. Results saved so far stay."] = "시뮬레이터 실행을 멈춥니다. 지금까지 저장된 결과는 남습니다.",
	["Stops this reminder."] = "이 알림을 끕니다.",
	["Stormpike Guard"] = "스톰파이크 경비대",
	["Stormstrike, Earth Shock and Windfury"] = "폭풍의 일격, 대지 충격, 질풍",
	["Stormwind"] = "스톰윈드",
	["Stormwind City"] = "스톰윈드",
	["Story"] = "이야기",
	["Story lines in chapters"] = "장으로 나눈 이야기",
	["Story motion"] = "이야기 움직임",
	["Story so far"] = "지금까지의 이야기",
	["Storybook"] = "그림책",
	["Storyteller"] = "이야기꾼",
	["Strength"] = "힘",
	["Style follows the layout"] = "레이아웃을 따르는 스타일",
	["Suggest"] = "추천",
	["Levels above you"] = "내 레벨보다 높은 레벨",
	["Suggest raids"] = "공격대 추천",
	["Suggest raids too"] = "공격대도 추천",
	["Suggestions"] = "추천",
	["Suggestions from other parts of EldoUI and from plugins."] = "EldoUI의 다른 부분과 플러그인에서 온 추천.",
	["Suggestions lean to"] = "추천 성향",
	["switched off"] = "꺼짐",
	["Switched off."] = "꺼졌습니다.",
	["Switches the Alts module on. Each character is added the next time you log in on it."] = "캐릭터 모듈을 켭니다. 각 캐릭터는 다음에 그 캐릭터로 접속할 때 추가됩니다.",
	["Switches the Loot Guide module on; My Adventure comes with it."] = "Loot Guide 모듈을 켭니다. 나의 모험도 함께 켜집니다.",
	["Switches the Loot Guide module on; quest starter hints come with it."] = "Loot Guide 모듈을 켭니다. 퀘스트 시작 아이템 힌트도 함께 켜집니다.",
	["Switches the Loot Guide module on; the Attunements tab comes with it."] = "Loot Guide 모듈을 켭니다. 입장 자격 탭도 함께 켜집니다.",
	["Switches the Loot Guide module on; the Zones section comes with it."] = "Loot Guide 모듈을 켭니다. 지역 항목도 함께 켜집니다.",
	["Switches the table. Each table keeps its search and filters for this session."] = "표를 바꿉니다. 각 표는 이번 접속 동안 검색과 필터를 유지합니다.",
	["Tabard"] = "휘장",
	["Tabards"] = "휘장",
	["Tailoring"] = "재봉술",
	["Take a screenshot"] = "스크린샷 찍기",
	["Take a screenshot with your screenshot key. Click or press Esc to close."] = "스크린샷 키로 스크린샷을 찍으세요. 클릭하거나 Esc를 누르면 닫힙니다.",
	["take it out of the planner"] = "계획표에서 빼기",
	["Take the tour"] = "안내 둘러보기",
	["Taken"] = "찍음",
	["Taken at %s. You find it in the Screenshots folder of your game."] = "%s에 찍었습니다. 게임의 Screenshots 폴더에 있습니다.",
	["taken before the journal kept track"] = "일지가 기록을 시작하기 전에 찍음",
	["Taken before the journal kept track."] = "일지가 기록을 시작하기 전에 찍었습니다.",
	["Taken off your keepsakes."] = "기념품에서 뺐습니다.",
	["Takes a backup of this journal now."] = "지금 이 일지를 백업합니다.",
	["Takes about %d minutes."] = { other = "약 %d분 걸립니다." },
	["Takes it off your keepsakes."] = "기념품에서 뺍니다.",
	["Takes one screenshot of the card, without this button and the hint. It goes to the Screenshots folder of your game."] = "이 버튼과 안내 문구 없이 카드만 스크린샷 한 장으로 찍습니다. 게임의 Screenshots 폴더에 저장됩니다.",
	["Takes step %d: %s"] = "%d단계 완료 보고: %s",
	["Takes this note off your Journey."] = "이 메모를 여정에서 뺍니다.",
	["Taking it with you"] = "가져가기",
	["Talents are read by name, which works on English game clients only. On this client the simulator plays without talent effects."] = "특성은 이름으로 읽으며 영어 게임 클라이언트에서만 됩니다. 이 클라이언트에서는 시뮬레이터가 특성 효과 없이 실행합니다.",
	["Talents the simulator plays"] = "시뮬레이터가 쓰는 특성",
	["Tank"] = "방어 전담",
	["Tank: avoidance pick (%s holds more threat)"] = "방어 전담: 회피 선택 (%s 쪽이 위협 수준이 더 높음)",
	["Tank: close call with %s"] = "방어 전담: %s와(과) 근소한 차이",
	["Tank: threat pick (%s holds more avoidance)"] = "방어 전담: 위협 선택 (%s 쪽이 회피가 더 높음)",
	["Target"] = "대상",
	["target level %d"] = "대상 레벨 %d",
	["Teaches"] = "가르침",
	["Tell the guild"] = "길드에 알리기",
	["Tell the guild button"] = "길드에 알리기 버튼",
	["Telling"] = "들려주기",
	["Tells you when a wishlist item is in a loot window or a roll, or drops in the dungeon you enter. It never loots or rolls for you."] = "위시리스트 아이템이 전리품 창이나 주사위 굴림에 있거나 들어간 던전에서 나올 때 알려 줍니다. 대신 줍거나 굴리지는 않습니다.",
	["Test alert"] = "알림 시험",
	["Text size of the story in the Book and Story so far, 90 to 140%."] = "책과 지금까지의 이야기에 쓰는 이야기 글자 크기, 90~140%.",
	["That backup is gone."] = "그 백업은 없어졌습니다.",
	["That dungeon is not in the dungeon list."] = "그 던전은 던전 목록에 없습니다.",
	["That goal could not be set."] = "그 목표를 설정할 수 없었습니다.",
	["That is not a journal code. Look for !EUJ1!, FJ2: or FJ1: at the start."] = "일지 코드가 아닙니다. 시작 부분에 !EUJ1!, FJ2: 또는 FJ1:가 있는지 확인하세요.",
	["That is one of your goals already."] = "이미 목표 중 하나입니다.",
	["That item does not go in an equipment slot."] = "그 아이템은 장비 칸에 들어가지 않습니다.",
	["That item does not go in this slot."] = "그 아이템은 이 칸에 들어가지 않습니다.",
	["That quest chain is not in the quest data."] = "그 퀘스트 연계는 퀘스트 데이터에 없습니다.",
	["The %s page is switched off on the Loot Guide settings page."] = "%s 페이지는 Loot Guide 설정 페이지에서 꺼져 있습니다.",
	["the address to report problems"] = "문제를 보고할 주소",
	["The adventurer's log: plain past tense, places and levels first."] = "모험가의 기록: 담백한 과거형, 장소와 레벨을 먼저.",
	["The Alts module stays off while %s is loaded, so only this character is known."] = "%s 애드온이 불러와져 있는 동안 캐릭터 모듈은 꺼져 있으므로 이 캐릭터만 알 수 있습니다.",
	["The Argent Dawn sends you to Naxxramas once you are Honored or better; each rank makes the way in cheaper."] = "은빛 여명회는 존경 이상이 되면 낙스라마스로 보냅니다. 등급이 오를수록 입장 비용이 줄어듭니다.",
	["The Attunements tab lives in the Loot Guide. Turn the Loot Guide on first."] = "입장 자격 탭은 Loot Guide 안에 있습니다. 먼저 Loot Guide를 켜세요.",
	["The Attunements tab lives in the Loot Guide. Turn the Loot Guide on to use it."] = "입장 자격 탭은 Loot Guide 안에 있습니다. 사용하려면 Loot Guide를 켜세요.",
	["The backup is merged into your journal."] = "백업을 일지에 합쳤습니다.",
	["The best gear you can get for your spec and level, your filter and stat order, and two plan sets of your own."] = "내 전문화와 레벨, 필터와 능력치 순서에 맞춰 얻을 수 있는 최고의 장비와 내 계획 세트 두 개.",
	["The best idea for right now and why it is here. A dungeon opens as a trip plan: the quests to pick up first, getting in, inside, and afterwards. Every button only shows you the way."] = "지금 가장 좋은 생각과 그 이유. 던전은 여행 계획으로 열립니다: 먼저 받을 퀘스트, 들어가기, 내부, 이후. 모든 버튼은 길만 보여 줍니다.",
	["The best item per slot from your list, what you wear, your two plan sets and your wishlist by slot. Click a slot to pick something else."] = "목록에서 부위별 최고 아이템, 착용 중인 것, 계획 세트 두 개와 부위별 위시리스트. 부위를 클릭해 다른 것을 고르세요.",
	["The best items on your list for your spec and the plan phase, one per slot. The number is the gain over what you wear."] = "내 전문화와 계획 단계에 맞는 목록의 최고 아이템, 부위마다 하나. 숫자는 착용 중인 것보다 나아지는 정도입니다.",
	["The card joins the suggestions again."] = "카드가 다시 추천에 들어갑니다.",
	["The cards you put away. They come back at your next level or after 24 hours."] = "치워 둔 카드입니다. 다음 레벨이 되거나 24시간이 지나면 돌아옵니다.",
	["The cards you sent off with Not now, with Bring back."] = "나중에로 보낸 카드와 되돌리기 버튼.",
	["The cards you sent off with Not now."] = "나중에로 보낸 카드.",
	["The chain as a chart: every step a box, lines to the steps that need it."] = "연계를 도표로: 단계마다 상자 하나, 그 단계가 필요한 단계로 이어지는 선.",
	["The check could not start."] = "확인을 시작할 수 없었습니다.",
	["The check is running: %d of %d quests asked. %s stops it."] = { other = "확인 중: 퀘스트 %d/%d개 질의. %s 명령으로 멈춥니다." },
	["The client does not know where this entrance is."] = "클라이언트가 이 입구의 위치를 모릅니다.",
	["The code is incomplete or damaged (%s). Copy all of it and paste it again."] = "코드가 불완전하거나 손상되었습니다 (%s). 전부 복사해서 다시 붙여 넣으세요.",
	["The code is incomplete or damaged. Copy all of it and paste it again."] = "코드가 불완전하거나 손상되었습니다. 전부 복사해서 다시 붙여 넣으세요.",
	["The commands and the address for problems. Pages, drop chances, the rating mode, alerts and the window look are in /eui > Loot Guide."] = "명령어와 문제 신고 주소. 페이지, 획득 확률, 평가 방식, 알림과 창 모양은 /eui > Loot Guide에 있습니다.",
	["The Crescent Key opens the doors of Dire Maul West and North; a boss in Dire Maul East drops it."] = "초승달 열쇠는 혈투의 전장 서부와 북부의 문을 엽니다. 혈투의 전장 동부의 우두머리가 떨어뜨립니다.",
	["The data has no place on your map for this quest's giver."] = "데이터에 이 퀘스트 제공자의 지도 위치가 없습니다.",
	["The database needs the loot data"] = "데이터베이스에는 전리품 데이터가 필요합니다",
	["The Defilers"] = "포세이큰 파멸단",
	["the details"] = "자세히 보기",
	["the details below"] = "아래 세부 정보",
	["The door opens at level %d."] = "문은 %d레벨에 열립니다.",
	["The drop data comes with the Loot Guide. Turn the Loot Guide on to use it."] = "획득 데이터는 Loot Guide에 들어 있습니다. 쓰려면 Loot Guide를 켜세요.",
	["The Drowned City"] = "The Drowned City",
	["the dummy cannot be stunned in a useful way"] = "허수아비는 쓸모 있게 기절시킬 수 없음",
	["the dummy does not hit back"] = "허수아비는 반격하지 않음",
	["the dungeon"] = "던전",
	["The EldoUI page and the place to report problems. Copy (Ctrl+C) and open them in your browser."] = "EldoUI 페이지와 문제 신고처. 복사해서(Ctrl+C) 브라우저에서 여세요.",
	["The EldoUI project page and the address to report a wrong drop or a problem, ready to copy."] = "EldoUI 프로젝트 페이지와 잘못된 전리품이나 문제를 신고할 주소. 복사할 수 있습니다.",
	["The entrance is %s."] = "%s 입구를 찾을 수 있습니다.",
	["The Exodar"] = "엑소다르",
	["The export did not work. The error is in the error list."] = "내보내기에 실패했습니다. 오류는 오류 목록에 있습니다.",
	["The filters hide every answer."] = "필터 때문에 모든 답이 숨겨졌습니다.",
	["The first faction that counts you as Honored."] = "나를 처음으로 존경으로 대한 평판.",
	["The first flight path you learned."] = "처음 익힌 비행 경로.",
	["The first one on %s. Take its items or money from a mailbox."] = "가장 먼저 만료되는 날: %s. 우편함에서 아이템이나 돈을 꺼내세요.",
	["The first page is still blank"] = "첫 페이지는 아직 비어 있습니다",
	["The first quest you handed in with a group."] = "파티와 함께 처음 완료한 퀘스트.",
	["The first rare you saw."] = "처음 본 희귀 몹.",
	["The first step is open: %s."] = "첫 단계가 열렸습니다: %s.",
	["The first time you died. It happens to everyone."] = "처음 죽은 때. 누구에게나 일어납니다.",
	["The first time you entered a dungeon."] = "처음 던전에 들어간 때.",
	["The first time you entered a raid."] = "처음 공격대에 들어간 때.",
	["The game could not save it. Try your own screenshot key."] = "게임이 저장할 수 없었습니다. 직접 스크린샷 키를 눌러 보세요.",
	["The game did not show your weapon skill, so the simulator used the usual skill for your level (5 per level)."] = "게임이 무기 숙련도를 알려주지 않아 시뮬레이터가 레벨에 맞는 기본 숙련도(레벨당 5)를 사용했습니다.",
	["The game does not list that faction for you yet. Check the spelling on your Reputation tab."] = "게임이 아직 그 평판을 보여 주지 않습니다. 평판 탭에서 철자를 확인하세요.",
	["The game does not list this dungeon yet. It shows here as soon as it does."] = "게임이 아직 이 던전을 보여 주지 않습니다. 보여 주는 즉시 여기에 나옵니다.",
	["The game does not report this step; it counts once the next one is done."] = "게임이 이 단계를 알려 주지 않습니다. 다음 단계를 마치면 완료로 칩니다.",
	["The game does not tell where this entrance is."] = "게임이 이 입구의 위치를 알려 주지 않습니다.",
	["The game has no map picture for this place. Here are its bosses in order; click one for its loot."] = "게임에 이 장소의 지도 그림이 없습니다. 우두머리를 순서대로 보여 드립니다. 클릭하면 전리품을 봅니다.",
	["The game has no name for that place yet."] = "게임에 아직 그 장소의 이름이 없습니다.",
	["The game has not sent this item's stats yet."] = "게임이 아직 이 아이템의 능력치를 보내지 않았습니다.",
	["the game marks it done"] = "게임이 완료로 표시함",
	["The game remembers %s quests you finished before the journal began."] = { other = "일지가 시작되기 전에 완료한 퀘스트 %s개를 게임이 기억합니다." },
	["the game remembers it as done"] = "게임이 완료로 기억함",
	["The game shows this rare on your minimap right now."] = "게임이 지금 미니맵에 이 희귀 몹을 표시합니다.",
	["The game's map could not place any creature camp. Open the world map once and come back."] = "게임 지도에서 몹 무리 위치를 찾지 못했습니다. 세계 지도를 한 번 열고 다시 오세요.",
	["The game's map says you are in this zone."] = "게임 지도상 이 지역에 있습니다.",
	["The game's own count of quests you completed."] = "게임이 직접 센 완료한 퀘스트 수.",
	["The game's own count of your deaths."] = "게임이 직접 센 죽은 횟수.",
	["The game's recommended levels."] = "게임이 권장하는 레벨입니다.",
	["The gear you wear; each slot shows how much its Best in Slot item adds."] = "착용 중인 장비. 각 부위에는 Best in Slot 아이템이 더해 주는 정도가 나옵니다.",
	["The group finder could not open here."] = "여기서는 파티 찾기를 열 수 없었습니다.",
	["The group finder opens after combat."] = "파티 찾기는 전투가 끝난 뒤 열립니다.",
	["The guide goes back to following your zone when your map changes."] = "지도가 바뀌면 가이드가 다시 현재 지역을 따라갑니다.",
	["The guide needs the loot data (the EldoUI_LootData addon) or the game's dungeon finder list to suggest trips."] = "여행을 추천하려면 전리품 데이터(EldoUI_LootData 애드온)나 게임의 던전 찾기 목록이 필요합니다.",
	["The guide needs the loot data (the EldoUI_LootData addon) or the game's dungeon finder list to suggest trips. Quests in your log still show here."] = "여행을 추천하려면 전리품 데이터(EldoUI_LootData 애드온)나 게임의 던전 찾기 목록이 필요합니다. 퀘스트 목록의 퀘스트는 여전히 여기에 나옵니다.",
	["The Hall of Thanes"] = "The Hall of Thanes",
	["The honor cost and PvP rank the item needs."] = "아이템에 필요한 명예 비용과 PvP 계급.",
	["The import is undone."] = "가져오기를 취소했습니다.",
	["The instance page with every boss, its quests and its trash loot."] = "모든 우두머리, 그 퀘스트와 일반 몹 전리품이 있는 인스턴스 페이지.",
	["The item; its color is its quality."] = "아이템. 색은 품질을 나타냅니다.",
	["the items that fit this slot"] = "이 칸에 맞는 아이템",
	["The items you see this boss drop are added here."] = "이 우두머리에게서 획득하는 것을 본 아이템이 여기에 추가됩니다.",
	["The journal as a readable document, by chapter, with goals, notes and quests. Companion names are left out."] = "장별로 목표, 메모, 퀘스트가 들어간 읽기 쉬운 문서 형태의 일지. 동료 이름은 빠집니다.",
	["The journal as a web page (HTML). Save it as a .html file, open it in a browser and print it to PDF. Opened outside the game it loads its fonts from Google Fonts."] = "웹 페이지(HTML) 형태의 일지. .html 파일로 저장해 브라우저에서 열고 PDF로 인쇄하세요. 게임 밖에서 열면 글꼴을 Google Fonts에서 불러옵니다.",
	["The journal as plain text, by chapter."] = "장별로 나눈 일반 텍스트 형태의 일지.",
	["The journal begins in %s"] = "일지의 시작: %s",
	["The journal has no company by that name."] = "일지에 그런 이름의 동료가 없습니다.",
	["The journal has not been here yet."] = "일지가 아직 이곳에 와 본 적이 없습니다.",
	["The journal is not ready yet. Try again in a moment."] = "일지가 아직 준비되지 않았습니다. 잠시 후 다시 시도하세요.",
	["The journal of %s, saved %s."] = "%s의 일지, 저장: %s.",
	["The journal shows what the game and your other EldoUI modules wrote down. Nothing is guessed."] = "일지는 게임과 다른 EldoUI 모듈이 기록한 것을 보여 줍니다. 추측한 것은 없습니다.",
	["The journal waits for the end of combat"] = "일지는 전투가 끝나길 기다립니다",
	["The Journal window's dark page and the EldoUI Book, the Storyteller detail with keepsakes, the tracker under your quests and moments in the alert lane."] = "일지 창의 어두운 페이지와 EldoUI 책, 기념품이 있는 이야기꾼 상세 화면, 퀘스트 아래의 추적기와 알림 줄의 순간.",
	["The Journal window's own dark page with the accent color."] = "강조 색이 들어간 일지 창 고유의 어두운 페이지.",
	["The journal's own rows: short, exact, with digits."] = "일지 고유의 줄: 짧고 정확하며 숫자로.",
	["The journal's pages are switched off or still loading."] = "일지 페이지가 꺼져 있거나 아직 불러오는 중입니다.",
	["The Journey's day view on the day you last played."] = "마지막으로 플레이한 날의 여정 일별 보기.",
	["The Key to the City opens the service gate of Stratholme; a boss inside drops it."] = "도시의 열쇠는 스트라솔름의 관리용 문을 엽니다. 안에 있는 우두머리가 떨어뜨립니다.",
	["The last one you had open"] = "마지막으로 열었던 것",
	["The last run is outdated: your level, gear, talents or list changed."] = "지난 실행 결과가 오래되었습니다: 레벨, 장비, 특성 또는 목록이 바뀌었습니다.",
	["The League of Arathor"] = "아라시 연맹",
	["The level log was off for these levels."] = "이 레벨 동안에는 레벨 기록이 꺼져 있었습니다.",
	["The level of the target dummy. Bosses are three levels above you: more misses, glancing blows and resists."] = "훈련용 허수아비의 레벨. 우두머리는 나보다 3레벨 높습니다: 빗맞힘, 빗나간 공격, 저항이 늘어납니다.",
	["The light part is rested experience: kills give double experience until it is used up."] = "밝은 부분은 휴식 경험치입니다: 다 쓸 때까지 처치 경험치가 두 배입니다.",
	["The line is in the chat box. Press Enter to send it, or Escape to drop it."] = "대화창에 문장이 들어가 있습니다. Enter를 눌러 보내거나 Esc를 눌러 버리세요.",
	["The list on the left leaves out attunements you have finished."] = "왼쪽 목록에는 완료한 입장 자격이 빠집니다.",
	["The long chain of Anachronos and the three dragonflights that opens the gates of Ahn'Qiraj."] = "아낙크로노스와 세 용군단의 긴 연계로, 안퀴라즈의 문을 엽니다.",
	["The long chain through Stormwind and Blackrock Spire ends with the Drakefire Amulet you need for Onyxia's Lair."] = "스톰윈드와 검은바위 첨탑을 거치는 긴 연계는 오닉시아의 둥지에 필요한 용암불꽃 목걸이로 끝납니다.",
	["the loot"] = "전리품",
	["The loot data does not list where this recipe comes from."] = "전리품 데이터에 이 제조법을 얻는 곳이 없습니다.",
	["The loot data has no place on your map for this."] = "전리품 데이터에 이것의 지도 위치가 없습니다.",
	["The loot data has no rares or named creatures for the zone you are in. Pick a zone on the left."] = "전리품 데이터에 현재 지역의 희귀 몹이나 이름 있는 몹이 없습니다. 왼쪽에서 지역을 고르세요.",
	["The loot data lists no bosses here."] = "전리품 데이터에 이곳의 우두머리가 없습니다.",
	["The loot data lists no crafts for this profession."] = "전리품 데이터에 이 전문기술의 제작품이 없습니다.",
	["The loot data lists no factions for your side."] = "전리품 데이터에 내 진영의 평판 진영이 없습니다.",
	["The loot data lists no factions of the other side."] = "전리품 데이터에 상대 진영의 평판 진영이 없습니다.",
	["The loot data lists no rewards for this faction."] = "전리품 데이터에 이 평판의 보상이 없습니다.",
	["The loot data lists no vendors, quest rewards or drops for this event."] = "전리품 데이터에 이 축제의 상인, 퀘스트 보상, 전리품이 없습니다.",
	["The Loot Guide opens out of combat."] = "Loot Guide는 전투가 끝난 뒤 열립니다.",
	["The Loot Guide stays off while %s is loaded."] = "%s 애드온이 불러와져 있는 동안 Loot Guide는 꺼져 있습니다.",
	["The lowest quality a find needs to be written on the Journey. Changing it on a preset turns it into Custom."] = "발견한 것이 여정에 기록되려면 필요한 최저 품질. 프리셋에서 바꾸면 사용자 설정이 됩니다.",
	["The mouse wheel turns the pages too."] = "마우스 휠로도 페이지를 넘깁니다.",
	["The next open step of each attunement and key."] = "각 입장 자격과 열쇠의 다음 열린 단계.",
	["The next step's quest giver on the map and toasts as you go."] = "지도에 다음 단계의 퀘스트 제공자를 표시하고 진행하면서 알림을 띄웁니다.",
	["The Night ledger Book in smaller text, short chapters and a slim tracker. Row size stays the Loot Guide's own setting."] = "작은 글자, 짧은 장, 얇은 추적기의 밤의 장부 책. 줄 크기는 Loot Guide 고유 설정을 따릅니다.",
	["The numbers come from many short fights with random rolls. The ± range shows how sure they are (95 %)."] = "숫자는 무작위 판정이 들어간 짧은 전투 여러 번에서 나옵니다. ± 범위는 그 확실성을 보여 줍니다 (95 %).",
	["The oldest %d are kept as counts on their levels."] = { other = "가장 오래된 %d개는 해당 레벨에 개수로만 남습니다." },
	["The oldest goes when a new one would pass this. The newest copy from before an EldoUI update has a slot of its own and is always kept."] = "새로 추가해서 이 수를 넘으면 가장 오래된 것이 지워집니다. EldoUI 업데이트 전의 가장 최근 사본은 별도의 자리가 있어 항상 보관됩니다.",
	["The order your spec values stats in. Drag to change it."] = "내 전문화가 능력치를 중시하는 순서. 드래그해서 바꾸세요.",
	["The page the window shows when you open it outside a dungeon. The gear holds a switch for each page and the Catalog's settings."] = "던전 밖에서 창을 열 때 보이는 페이지. 톱니바퀴에 페이지마다 스위치와 목록 설정이 있습니다.",
	["the page you left, even inside a dungeon"] = "던전 안에서도 마지막 페이지",
	["The pages of My Adventure on the Journal window's own dark panel, or on parchment with dark ink. The Book and the character card keep their own Book look."] = "나의 모험 페이지를 일지 창 고유의 어두운 판 위에, 또는 진한 잉크의 양피지 위에 보여 줍니다. 책과 캐릭터 카드는 고유의 책 모양을 유지합니다.",
	["The people you grouped with last first."] = "최근에 함께한 사람부터.",
	["The people you met and grouped with."] = "만나고 함께 파티를 한 사람들.",
	["The people you spent the most time with first."] = "가장 오래 함께한 사람부터.",
	["The people you traveled with: time together and how it was spent, dungeons and quests together, and your notes on them."] = "함께 여행한 사람들: 함께한 시간과 그 시간을 보낸 방식, 함께한 던전과 퀘스트, 그들에 대한 메모.",
	["The places you came to last first."] = "최근에 온 장소부터.",
	["The places you spent the most time in first."] = "가장 오래 머문 장소부터.",
	["The planner is already empty."] = "계획이 이미 비어 있습니다.",
	["The planner is empty."] = "계획을 비웠습니다.",
	["The PvP planner works out weeks from this. Leave 0 to use what you earned in recent weeks."] = "PvP 계획표는 이것으로 주 수를 계산합니다. 0으로 두면 최근 몇 주 동안 얻은 양을 씁니다.",
	["The quest chains come from EldoUI_LootData, which loads a few seconds after login."] = "퀘스트 연계는 접속 후 몇 초 뒤에 불러오는 EldoUI_LootData에서 옵니다.",
	["The quest giver is %s."] = "%s 퀘스트 제공자를 만날 수 있습니다.",
	["The quest giver's exclamation mark right of the bar, like the game's quest icon."] = "막대 오른쪽의 퀘스트 제공자 느낌표, 게임의 퀘스트 아이콘처럼.",
	["The quest givers are %s."] = "%s 퀘스트 제공자들을 만날 수 있습니다.",
	["The quest tracker leaves room at its bottom for the journal tracker. With Questie, the journal tracker sits right under Questie's list."] = "퀘스트 추적기는 아래에 일지 추적기 자리를 남깁니다. Questie를 쓰면 일지 추적기는 Questie 목록 바로 아래에 붙습니다.",
	["The quests for this instance with your status: open, done or locked."] = "이 인스턴스의 퀘스트와 내 상태: 진행 가능, 완료 또는 잠김.",
	["The quests you archived, with Restore."] = "보관한 퀘스트와 복원 버튼.",
	["The reminder stays and shows each time, instead of once."] = "알림이 남아 있다가 한 번이 아니라 매번 나옵니다.",
	["The reputation the item needs, red while you are below it."] = "아이템에 필요한 평판. 모자라는 동안 빨간색입니다.",
	["The road is waiting. Every zone you visit gets a card."] = "길이 기다립니다. 방문하는 지역마다 카드가 생깁니다.",
	["The role they had when they sent it."] = "보낼 때 그 사람의 역할.",
	["The same fights (same dice) for every set, so the differences are steadier than the totals."] = "모든 세트에 같은 전투(같은 주사위)를 쓰므로 차이가 합계보다 안정적입니다.",
	["The Seal of Ascension opens the doors of Upper Blackrock Spire for your whole group."] = "승천의 인장은 파티 전체에게 검은바위 첨탑 상층의 문을 엽니다.",
	["The search index is built out of combat. Try again in a moment."] = "검색 색인은 전투가 끝난 뒤 만들어집니다. 잠시 후 다시 시도하세요.",
	["The search looks through the %s table."] = "%s 표에서 검색합니다.",
	["The section My Adventure opens on: Today, a page you pick (Next trips, Journey, Book, Story so far, Keepsakes, Places, Quests, Fellowship, Goals or Notes), or the last one you had open."] = "나의 모험이 처음 여는 구역: 오늘, 고른 페이지(다음 여행, 여정, 책, 지금까지의 이야기, 기념품, 장소, 퀘스트, 동료애, 목표 또는 메모), 또는 마지막으로 열었던 것.",
	["The section you came back from. Alt+Right does the same."] = "돌아왔던 구역. Alt+오른쪽 화살표도 같습니다.",
	["The section you had open before. Alt+Left or Backspace does the same."] = "전에 열었던 구역. Alt+왼쪽 화살표나 Backspace도 같습니다.",
	["The set an item is part of (owned of total) and what a token buys."] = "아이템이 속한 세트(가진 수/전체)와 토큰으로 살 수 있는 것.",
	["The set bonuses show once the game has the pieces' details (hover a piece once)."] = "세트 효과는 게임이 각 부위의 정보를 받은 뒤 나옵니다 (부위 위에 한 번 마우스를 올리세요).",
	["The set is shared with the Best in Slot page. This can't be undone."] = "이 세트는 Best in Slot 페이지와 공유됩니다. 되돌릴 수 없습니다.",
	["The Shadowforge Key opens the gates deeper in Blackrock Depths."] = "어둠괴철로 만든 열쇠는 검은바위 나락 깊은 곳의 문을 엽니다.",
	["The Shapers Terrace"] = "The Shapers Terrace",
	["The simulation is done."] = "시뮬레이션이 끝났습니다.",
	["The simulator could not start."] = "시뮬레이터를 시작할 수 없었습니다.",
	["The simulator folder EldoUI_LootSim is not installed. It comes with EldoUI: put it next to the EldoUI folder in Interface\\AddOns."] = "시뮬레이터 폴더 EldoUI_LootSim이 설치되지 않았습니다. EldoUI에 함께 들어 있으니 Interface\\AddOns의 EldoUI 폴더 옆에 넣으세요.",
	["The simulator found no damage spells it can use yet."] = "시뮬레이터가 아직 쓸 수 있는 피해 주문을 찾지 못했습니다.",
	["The simulator has no model for your class."] = "시뮬레이터에 내 직업의 모델이 없습니다.",
	["The simulator has no numbers for this item yet."] = "시뮬레이터에 아직 이 아이템의 수치가 없습니다.",
	["The simulator has no stats for these items, so sets with them are not simulated: "] = "시뮬레이터에 이 아이템들의 능력치가 없어서 이 아이템이 든 세트는 시뮬레이션하지 않습니다: ",
	["The simulator runs out of combat. Try again when the fight is over."] = "시뮬레이터는 전투 중이 아닐 때 실행됩니다. 전투가 끝나면 다시 시도하세요.",
	["The Skeleton Key opens the gates of Scholomance."] = "해골 열쇠는 스칼로맨스의 문을 엽니다.",
	["The sound that plays with a wishlist alert."] = "위시리스트 알림과 함께 나는 소리.",
	["The step is %s."] = "%s 이 단계를 진행합니다.",
	["The step is ready to hand in."] = "단계를 완료 보고할 수 있습니다.",
	["the story of this quest"] = "이 퀘스트의 이야기",
	["The suggestions again."] = "다시 추천.",
	["The tab lists attunements, keys and dungeon quests once the quest data is loaded."] = "퀘스트 데이터를 불러오면 이 탭에 입장 자격, 열쇠, 던전 퀘스트가 나옵니다.",
	["The tavern song: warm and vivid, never false."] = "선술집 노래: 따뜻하고 생생하게, 거짓 없이.",
	["The tour runs out of combat."] = "안내는 전투가 아닐 때 진행됩니다.",
	["The view the Overview button opens first."] = "개요 버튼이 처음 여는 보기.",
	["The Warlord's Command chain through Blackrock Spire ends with the Drakefire Amulet you need for Onyxia's Lair."] = "검은바위 첨탑을 거치는 대장군의 명령 연계는 오닉시아의 둥지에 필요한 용암불꽃 목걸이로 끝납니다.",
	["The whole Book in this tone as plain text, in a copy box."] = "이 어조로 쓴 책 전체를 복사 상자에 일반 텍스트로.",
	["The whole journal as one code, to keep or to paste in on another PC. Nothing is sent anywhere."] = "일지 전체를 코드 하나로. 보관하거나 다른 PC에 붙여 넣을 수 있습니다. 아무 데도 보내지 않습니다.",
	["The whole story in this tone as plain text, in a copy box."] = "이 어조로 쓴 이야기 전체를 복사 상자에 일반 텍스트로.",
	["The whole story with headings, for a website, a forum, or Discord."] = "웹사이트, 포럼 또는 Discord용 제목이 붙은 이야기 전체.",
	["The window lets the game show through a little. How much: General > Panel opacity. Drag the window's corner grip to change its size."] = "창 너머로 게임이 살짝 비쳐 보입니다. 정도: General > Panel opacity. 창 모서리 손잡이를 끌어 크기를 바꿉니다.",
	["The zone is %d-%d; you are level %d."] = "이 지역은 %d~%d레벨이고 내 레벨은 %d입니다.",
	["The zone list is built out of combat. It shows once the fight is over."] = "지역 목록은 비전투 중에 만들어집니다. 전투가 끝나면 표시됩니다.",
	["The Zones section lives in the Loot Guide. Turn the Loot Guide on to use it."] = "지역 항목은 Loot Guide에 있습니다. 쓰려면 Loot Guide를 켜세요.",
	["There is no import to undo."] = "취소할 가져오기가 없습니다.",
	["There is no journal to back up yet."] = "아직 백업할 일지가 없습니다.",
	["There is no journal to export yet."] = "아직 내보낼 일지가 없습니다.",
	["There is no live position inside dungeons."] = "던전 안에서는 실시간 위치가 없습니다.",
	["They come back at your next level or after 24 hours."] = "다음 레벨이 되거나 24시간이 지나면 돌아옵니다.",
	["They may be in another character's fellowship."] = "다른 캐릭터의 동료애에 있을 수 있습니다.",
	["They were level %s."] = "그들은 %s레벨이었습니다.",
	["Things you want to work towards. Their progress moves by itself as the game reports it."] = "이루고 싶은 목표. 진행도는 게임이 알려 주는 대로 저절로 움직입니다.",
	["This backup is still being written. Try again in a moment."] = "이 백업은 아직 기록 중입니다. 잠시 후 다시 시도하세요.",
	["This can't be undone."] = "되돌릴 수 없습니다.",
	["This client"] = "이 클라이언트",
	["This client cannot set a map pin."] = "이 클라이언트는 지도 핀을 설정할 수 없습니다.",
	["This client has no group finder window."] = "이 클라이언트에는 파티 찾기 창이 없습니다.",
	["This code contains only recent changes. Merge adds them to your journal and keeps your existing entries."] = "이 코드에는 최근 변경 사항만 들어 있습니다. 합치기를 누르면 기존 항목을 유지하면서 일지에 추가합니다.",
	["This game client cannot answer quest questions."] = "이 게임 클라이언트는 퀘스트 질의에 답할 수 없습니다.",
	["This game client does not tell add-ons about poisons, oils and other temporary weapon enchants, so they are not counted."] = "이 게임 클라이언트는 독, 오일 같은 임시 무기 마법부여를 애드온에 알려 주지 않으므로 계산하지 않습니다.",
	["This is how wishlist alerts look."] = "위시리스트 알림은 이렇게 보입니다.",
	["this is not a Best in Slot string"] = "Best in Slot 문자열이 아닙니다",
	["this is not a wishlist string"] = "위시리스트 문자열이 아닙니다",
	["This list is already empty."] = "이 목록은 이미 비어 있습니다.",
	["This list shows the factions you have met. Show all factions to see every faction's rewards."] = "이 목록은 만난 진영을 보여 줍니다. 모든 진영 표시로 모든 진영의 보상을 봅니다.",
	["This page shows where to go next and what is waiting for you."] = "이 페이지는 다음에 갈 곳과 기다리고 있는 것을 보여 줍니다.",
	["This place cannot be shown on your map."] = "이 장소는 지도에 표시할 수 없습니다.",
