	["Turn Forever Journal off in the AddOns list and reload, so the two journals do not both write."] = "두 일지가 동시에 기록하지 않도록 애드온 목록에서 Forever Journal을 끄고 UI를 다시 불러오세요.",
	["Turn in: %s"] = "완료 보고: %s",
