	["Turn on Blizzard UI > Objective / quest tracker > Move and scale to keep the quest list clear of the journal tracker."] = "퀘스트 목록이 일지 추적기에 가리지 않도록 Blizzard UI > Objective / quest tracker > Move and scale을 켜세요.",
	["Turn on sharing"] = "공유 켜기",
	["Turn on sharing to ask guild and group members who use EldoUI for their attunements and to send yours. Nothing is sent until you click Ask or Send mine."] = "공유를 켜면 EldoUI를 쓰는 길드원과 파티원에게 입장 자격을 묻고 내 것을 보낼 수 있습니다. 묻기나 내 것 보내기를 누르기 전에는 아무것도 보내지 않습니다.",
	["Turn on the Alts module to see the attunements of your other characters here."] = "다른 캐릭터의 입장 자격을 여기서 보려면 캐릭터 모듈을 켜세요.",
	["Turn on the Loot Guide"] = "Loot Guide 켜기",
