	["Type"] = "종류",
	["Type %s in chat for the My Adventure settings."] = "나의 모험 설정은 대화창에 %s 입력하세요.",
	["Type a little more"] = "조금 더 입력하세요",
	["Type the creature's name, or use your target."] = "몹의 이름을 입력하거나 대상을 쓰세요.",
	["Type the dungeon's name, for example The Deadmines."] = "던전 이름을 입력하세요. 예: 죽음의 폐광.",
	["Type the faction's name, for example Stormwind."] = "평판 이름을 입력하세요. 예: 스톰윈드.",
