	["Type the profession's name, for example First Aid."] = "전문기술 이름을 입력하세요. 예: 응급치료.",
	["Type three letters in the box at the top (or an alias such as dm or zf) and press Enter."] = "위쪽 칸에 세 글자(또는 dm이나 zf 같은 줄임말)를 입력하고 Enter를 누르세요.",
