	["Upgrades only hides creatures with nothing for you. Map on a rare card pins its camps, one per click."] = "상위 장비만은 내게 줄 것이 없는 몹을 숨깁니다. 희귀 몹 카드의 지도는 클릭할 때마다 그 몹의 무리 위치를 하나씩 표시합니다.",
