	["Walks through every page of the Loot Guide again, and shows the small tours of the filter, dungeon map and simulator again too."] = "Loot Guide의 모든 페이지를 다시 둘러보고, 필터, 던전 지도, 시뮬레이터의 짧은 안내도 다시 보여 줍니다.",
