	["What is left are raids, attunements, and reputation. Next trips shows them once you turn on raids, and the Attunements page has every key."] = "남은 것은 공격대, 입장 자격, 평판입니다. 공격대를 켜면 다음 여행에 나오고, 입장 자격 페이지에 모든 열쇠가 있습니다.",
	["What is left are raids, attunements, and reputation. Nothing else fits right now; put-away cards come back after 24 hours."] = "남은 것은 공격대, 입장 자격, 평판입니다. 지금은 다른 맞는 것이 없습니다. 치워 둔 카드는 24시간 뒤에 돌아옵니다.",
