	["What shows"] = "표시 항목",
	["What the game's quest lines report on this map. Copy it (Ctrl+C) and send it to EldoUI's authors."] = "이 지도에서 게임의 퀘스트 라인이 알려 주는 것. 복사해서(Ctrl+C) EldoUI 제작자에게 보내 주세요.",
	["What the item adds over what you wear, with your stat priority."] = "능력치 우선순위에 따라 아이템이 착용 장비보다 더해 주는 것.",
	["What the journal writes down, the look of its pages, and how the ideas are ranked. /eui tour journal shows this tour again."] = "일지가 기록하는 것, 페이지 모양, 아이디어 순위. /eui tour journal 명령으로 이 안내를 다시 봅니다.",
	["What the journal wrote down since you last logged out."] = "마지막으로 접속을 종료한 뒤 일지가 기록한 것.",
	["What the pages show"] = "페이지에 보이는 것",
	["What the tab has loaded. Chains come from EldoUI_LootData (Classic values; WoW: Forever may differ)."] = "탭이 불러온 것. 연계는 EldoUI_LootData에서 옵니다 (Classic 값이며 WoW: Forever와 다를 수 있음).",
	["What was read"] = "읽은 것",
	["What would you like to work towards?"] = "무엇을 목표로 삼고 싶으신가요?",
	["What you wear, Best in Slot and your plan sets compared as DPS from the same fights."] = "착용 장비, Best in Slot, 계획 세트를 같은 전투의 DPS로 비교합니다.",
	["When a backup is taken by itself, 8 seconds after you log in and out of combat."] = "백업이 저절로 만들어지는 때: 접속 8초 후, 전투 중이 아닐 때.",
	["When someone asks"] = "누군가 물어볼 때",
	["When this note should show again as a reminder. It picks one from what you write until you choose yourself."] = "이 메모를 언제 다시 알림으로 보여 줄지. 직접 고르기 전까지는 쓴 내용에서 하나를 고릅니다.",
	["When you apply a layout preset, the Book takes the look of the style that fits it: EldoUI, Storybook or Compact. What the journal shows is kept."] = "레이아웃 프리셋을 적용하면 책은 그에 맞는 스타일의 모양을 따릅니다: EldoUI, 그림책 또는 간단히. 일지가 보여 주는 내용은 유지됩니다.",
	["When you enter %s"] = "%s에 들어갈 때",
	["When you open a profession"] = "전문기술 창을 열 때",
	["When you reach level %d"] = "%d레벨에 도달할 때",
	["Where"] = "위치",
	["Where it began"] = "시작한 곳",
	["where it drops"] = "나오는 곳",
	["Where next"] = "다음 행선지",
	["Where recipes come from needs EldoUI_LootData. Install it next to EldoUI to see trainers, vendors, drops and quests."] = "제조법 획득처를 보려면 EldoUI_LootData가 필요합니다. 상급자, 상인, 전리품, 퀘스트를 보려면 EldoUI 옆에 설치하세요.",
	["Where the alert shows. Every alert also writes one chat line so you can read it later."] = "알림이 나오는 곳. 모든 알림은 나중에 읽을 수 있도록 대화창에도 한 줄 씁니다.",
	["Where the icon sits on the plate. Right of the bar comes after the elite and quest icons."] = "이름표에서 아이콘이 놓일 곳. 막대 오른쪽은 정예 아이콘과 퀘스트 아이콘 다음에 옵니다.",
	["Where the item drops and how often, and the vendors that sell it with the cost. Hold Shift for more sources and the drops you saw yourself."] = "아이템이 나오는 곳과 빈도, 파는 상인과 가격. Shift를 누르면 더 많은 획득처와 직접 본 전리품이 나옵니다.",
	["where the loot data comes from"] = "전리품 데이터의 출처",
	["Where this comes from"] = "출처",
	["Where to go"] = "갈 곳",
	["Where to go next and why: dungeons with their quests, quests that fit your level, attunement steps, and zones to explore."] = "다음에 갈 곳과 이유: 퀘스트가 있는 던전, 레벨에 맞는 퀘스트, 입장 자격 단계, 탐험할 지역.",
	["Where to go next, what is waiting for you, and what just happened."] = "다음에 갈 곳, 기다리고 있는 것, 방금 있었던 일.",
	["Where to go now and what you get there: the best dungeon for your level, your next upgrades and your best-in-slot progress."] = "지금 갈 곳과 그곳에서 얻는 것: 내 레벨에 가장 좋은 던전, 다음 상위 장비, Best in Slot 진행도.",
	["Where you left it"] = "두고 온 곳",
	["Where you left off"] = "멈춘 곳",
	["where you took it"] = "받은 곳",
	["Which attunement?"] = "어떤 입장 자격?",
	["Which attunements the columns show."] = "열에 보여 줄 입장 자격.",
	["Which classes the Class quests group lists."] = "직업 퀘스트 묶음에 나열할 직업.",
	["Which creature?"] = "어떤 몹?",
	["Which dungeon?"] = "어떤 던전?",
	["Which faction's steps the chain shows. Steps for both factions always show."] = "연계에 보여 줄 진영의 단계. 두 진영 공통 단계는 항상 보입니다.",
	["Which faction's steps the chains show (the same as the setting). Steps for both factions always show."] = "연계들에 보여 줄 진영의 단계 (설정과 같음). 두 진영 공통 단계는 항상 보입니다.",
	["Which faction?"] = "어떤 평판?",
	["Which item?"] = "어떤 아이템?",
	["Which level?"] = "몇 레벨?",
	["Which place?"] = "어떤 장소?",
	["Which profession?"] = "어떤 전문기술?",
	["Which quest?"] = "어떤 퀘스트?",
	["Which quests of each zone you have done and which are left, as a Catalog section of the Loot Guide, with the quest givers on the world map."] = "각 지역에서 완료한 퀘스트와 남은 퀘스트를 Loot Guide 목록의 항목으로 보여 주고, 퀘스트 제공자를 세계 지도에 표시합니다.",
	["Which skill level?"] = "어떤 숙련도?",
	["Which standing?"] = "어떤 등급?",
	["Whisper"] = "귓속말",
	["whisper, invite or remove"] = "귓속말, 초대 또는 제거",
	["Who is attuned: your characters, or guild and group members who shared theirs."] = "입장 자격이 있는 사람: 내 캐릭터, 또는 자기 것을 공유한 길드원과 파티원.",
	["Who you are and how far this level is. The light part of the bar is rested experience; the time to the next level counts only your own last levels."] = "내가 누구이고 이 레벨이 얼마나 진행되었는지. 막대의 밝은 부분은 휴식 경험치이고, 다음 레벨까지의 시간은 내 최근 레벨만으로 셉니다.",
	["Whose quests the list shows: yours, Alliance, Horde or both."] = "목록에 보여 줄 퀘스트: 내 것, 얼라이언스, 호드 또는 둘 다.",
	["Why"] = "이유",
	["Why not higher?"] = "왜 더 높지 않나요?",
	["Windfury"] = "질풍",
	["Windfury Weapon"] = "질풍의 무기",
	["Window"] = "창",
	["window position and size back to the default"] = "창 위치와 크기를 기본값으로",
	["Window sounds"] = "창 소리",
	["Wintersaber Trainers"] = "눈호랑이 조련사",
	["Wish"] = "원함",
