	["Wishlist alerts"] = "위시리스트 알림",
	["Wishlist first, compact rows, every quality, wishlist alerts as alert cards."] = "위시리스트 먼저, 간단한 줄, 모든 품질, 위시리스트 알림은 알림 카드로.",
	["Wishlist item"] = "위시리스트 아이템",
	["Wishlist item found: %s"] = "위시리스트 아이템 발견: %s",
	["wishlist, link, try on, plan sets, Wowhead link"] = "위시리스트, 링크, 착용해 보기, 계획 세트, Wowhead 링크",
	["Wishlists"] = "위시리스트",
	["Wishlists go only to your group, your guild or friends."] = "위시리스트는 내 파티, 길드 또는 친구에게만 보냅니다.",
	["With %s"] = "함께: %s",
	["With all checked, nothing is filtered."] = "모두 체크하면 아무것도 거르지 않습니다.",
	["With upgrades for me"] = "내 상위 장비가 있는 것",
