	["World events"] = "축제",
	["World events come from EldoUI_LootData. Install it next to EldoUI to list them."] = "축제는 EldoUI_LootData에서 옵니다. 목록을 보려면 EldoUI 옆에 설치하세요.",
	["World map"] = "세계 지도",
	["World needs the loot data"] = "세계에는 전리품 데이터가 필요합니다",
	["Worn"] = "착용함",
	["worn, in your bags, or in the bank"] = "착용 중, 가방 또는 은행에 있음",
	["worse than Earth Shock on a dummy"] = "허수아비에게 대지 충격보다 약함",
	["worse than Shadow Bolt on a dummy"] = "허수아비에게 어둠의 화살보다 약함",
	["WoW: Forever"] = "WoW: Forever",
	["WoW: Forever has announced this instance. Its loot shows here once it opens and drops are seen."] = "WoW: Forever가 이 인스턴스를 발표했습니다. 열리고 전리품이 확인되면 여기에 나옵니다.",
	["WoW: Forever's 10-player raid in Mount Hyjal. No attunement has been announced."] = "하이잘 산에 있는 WoW: Forever의 10인 공격대입니다. 입장 자격은 발표되지 않았습니다.",
	["WoW: Forever's 20-player raid in Mount Hyjal. No attunement has been announced."] = "하이잘 산에 있는 WoW: Forever의 20인 공격대입니다. 입장 자격은 발표되지 않았습니다.",
	["Wrist"] = "손목",
	["Write a note"] = "메모 쓰기",
	["Write a note about it"] = "이것에 대해 메모 쓰기",
	["Write a note on it"] = "여기에 메모 쓰기",
	["write a quick note"] = "빠른 메모 쓰기",
	["Write about this place, a reminder for later, or shift-click an item into it."] = "이 장소에 대해 쓰거나, 나중을 위한 알림을 쓰거나, Shift+클릭으로 아이템을 넣으세요.",
	["Write down what this character does: levels, places, quests, finds, people, goals and notes. Off: the journal keeps what it has and adds nothing."] = "이 캐릭터가 하는 일을 기록합니다: 레벨, 장소, 퀘스트, 발견, 사람, 목표, 메모. 끄면 일지는 가진 것을 유지하고 아무것도 더하지 않습니다.",
	["Write something first."] = "먼저 무언가를 쓰세요.",
	["Write the journal"] = "일지 쓰기",
	["Write the names of people you grouped with. They are left out of the character card and exports unless you check them there."] = "함께 파티를 한 사람들의 이름을 기록합니다. 거기서 체크하지 않으면 캐릭터 카드와 내보내기에서 빠집니다.",
	["Write what you want to do."] = "하고 싶은 일을 쓰세요.",
	["Writes the note into your journal with where and when you wrote it."] = "쓴 장소와 시간과 함께 메모를 일지에 적습니다.",
	["Writing"] = "쓰기",
	["Written by %s on %s."] = "작성: %s, %s.",
	["You"] = "나",
	["You already have that standing."] = "이미 그 등급입니다.",
	["You are %d of %d steps in."] = { other = "%d/%d단계 진행 중입니다." },
	["You are here"] = "현재 위치",
	["You are here."] = "현재 위치입니다.",
	["You are level %d"] = "내 레벨: %d",
	["You are not %s."] = "지금 %s 활동하고 있지 않습니다.",
	["You are not in a raid group; this is a raid of %d."] = "공격대에 속해 있지 않습니다. 이곳은 %d인 공격대입니다.",
	["You are not in Bear Form. Shift and press Sim again."] = "곰 변신 상태가 아닙니다. 변신하고 Sim을 다시 누르세요.",
	["You are not in Cat Form. Shift and press Sim again."] = "표범 변신 상태가 아닙니다. 변신하고 Sim을 다시 누르세요.",
	["You are on your own; this is a %d-player dungeon."] = "혼자입니다. 이곳은 %d인 던전입니다.",
	["You are resting: rested XP builds four times as fast here."] = "휴식 중: 여기서는 휴식 경험치가 네 배 빨리 쌓입니다.",
	["You are saved to it until the reset."] = "초기화될 때까지 귀속되어 있습니다.",
	["You came here before the journal kept dates."] = "일지가 날짜를 기록하기 전에 여기에 왔습니다.",
	["You can learn them now."] = "지금 배울 수 있습니다.",
	["You can take this quest now."] = "지금 이 퀘스트를 받을 수 있습니다.",
	["You can't Need on this roll."] = "이 주사위 굴림에서는 입찰을 선택할 수 없습니다.",
	["You can't use this"] = "사용할 수 없음",
	["You can't use this weapon type"] = "사용할 수 없는 무기 종류",
	["You can't wear this armor"] = "착용할 수 없는 방어구",
	["You defeated one of these this session."] = "이번 접속에서 이들 중 하나를 처치했습니다.",
	["You do not have this profession."] = "이 전문기술이 없습니다.",
	["You do not know this recipe yet."] = "아직 이 제조법을 모릅니다.",
	["You finished %s; the next part is waiting."] = "%s 완료. 다음 부분이 기다립니다.",
	["You have %d quests %s in your log."] = { other = "퀘스트 목록에 퀘스트 %d개가 있습니다: %s." },
	["You have %s."] = "보유: %s.",
	["You have about an hour: trips that fit it rank higher."] = "약 한 시간이 있습니다: 그에 맞는 여행이 위로 올라갑니다.",
	["You have about half an hour: trips that fit it rank higher."] = "약 30분이 있습니다: 그에 맞는 여행이 위로 올라갑니다.",
	["You have about two hours: trips that fit it rank higher."] = "약 두 시간이 있습니다: 그에 맞는 여행이 위로 올라갑니다.",
	["You have already done that quest."] = "이미 완료한 퀘스트입니다.",
	["You have already finished that quest chain."] = "이미 완료한 퀘스트 연계입니다.",
	["You have been here %d times."] = { other = "여기에 %d번 왔습니다." },
	["You have been here."] = "여기에 와 본 적이 있습니다.",
	["You have done this quest."] = "이 퀘스트를 완료했습니다.",
	["You have it"] = "보유 중",
	["You have not been inside yet."] = "아직 안에 들어가 본 적이 없습니다.",
	["You have not grouped on this character yet; your player notes know them."] = "이 캐릭터로는 아직 파티를 한 적이 없습니다. 플레이어 메모가 그들을 압니다.",
	["You have not met this faction yet."] = "아직 이 평판을 만나지 않았습니다.",
	["You have run dungeons with %s adventurers."] = { other = "모험가 %s명과 던전을 돌았습니다." },
	["You have shared the road with %s adventurers, %s in all."] = { other = "모험가 %s명과 길을 함께했습니다. 모두 %s." },
	["You have them all."] = "모두 가지고 있습니다.",
	["You imported before: only what is new since then comes in."] = "전에 가져온 적이 있습니다: 그 뒤로 새로 생긴 것만 들어옵니다.",
	["You know this recipe."] = "이 제조법을 알고 있습니다.",
	["You left %s with a quest unfinished."] = "퀘스트를 끝내지 않은 채 떠난 곳: %s.",
	["You missed one"] = "하나를 놓쳤습니다",
	["You need %d skill to learn it."] = "배우려면 숙련도 %d이 필요합니다.",
	["You own something better"] = "더 좋은 것을 가지고 있음",
	["You ran dungeons together before the journal kept company."] = "일지가 동료를 기록하기 전에 함께 던전을 돌았습니다.",
	["You ran it %d times at this level."] = { other = "이 레벨에서 %d번 돌았습니다." },
	["You rate items with the simulator: this runs your Best in Slot set now (out of combat, in small steps)."] = "시뮬레이터로 아이템을 평가하는 중: 지금 Best in Slot 세트를 실행합니다 (전투 중이 아닐 때, 조금씩).",
	["you wear it"] = "착용 중",
	["You wear this item"] = "이 아이템을 착용하고 있습니다",
	["You were away %s."] = "%s 동안 자리를 비웠습니다.",
	["You were away %s. You left off in %s at level %d."] = "%s 동안 자리를 비웠습니다. %s에서 %d레벨로 멈췄습니다.",
	["You were away %s. You left off in %s."] = "%s 동안 자리를 비웠습니다. %s에서 멈췄습니다.",
	["Your /played time, from the game."] = "게임이 알려 주는 /played 시간.",
	["Your active goals under the quest tracker. Click a to-do to check it."] = "퀘스트 추적기 아래의 진행 중인 목표. 할 일을 클릭하면 체크합니다.",
	["Your active wishlist by slot. Click a slot to choose its main pick; the model wears the picks."] = "부위별 활성 위시리스트. 부위를 클릭해 주 선택을 고르면 모델이 그것을 입습니다.",
	["Your active wishlist has no gear. Star items in the Journal or Search; they show here by slot."] = "활성 위시리스트에 장비가 없습니다. 일지나 검색에서 아이템에 별표를 다세요. 여기에 부위별로 나옵니다.",
	["Your Best in Slot run is outdated."] = "Best in Slot 실행 결과가 오래되었습니다.",
	["Your big moments as cards: first kills, epic finds, standings, mounts, and the moments you kept, with your firsts."] = "카드로 보는 큰 순간: 첫 처치, 영웅 발견, 평판 등급, 탈것, 보관한 순간과 처음 해 본 일들.",
	["Your big moments at these levels."] = "이 레벨들의 큰 순간.",
	["Your character card"] = "내 캐릭터 카드",
	["Your character card as a few lines of text. Companion names are left out."] = "몇 줄의 텍스트로 된 캐릭터 카드. 동료 이름은 빠집니다.",
	["Your character card as Markdown"] = "Markdown 형식 캐릭터 카드",
	["Your character card on a dimmed screen, ready for your own screenshot key."] = "어두워진 화면 위의 캐릭터 카드. 직접 스크린샷 키를 누르면 됩니다.",
	["Your character's journal, the first tab of this window: where to go next, what is waiting for you, and everything you have done."] = "이 창의 첫 탭인 캐릭터 일지: 다음에 갈 곳, 기다리고 있는 것, 지금까지 한 모든 일.",
	["Your character's journal: what you did and where, keepsakes, goals, notes, attunements, and where to go next."] = "캐릭터 일지: 무엇을 어디서 했는지, 기념품, 목표, 메모, 입장 자격, 다음에 갈 곳.",
	["Your character's journal: where to go next, what is waiting for you, your goals and notes, and the story so far. /eui tour journal shows it part by part."] = "캐릭터 일지: 다음에 갈 곳, 기다리고 있는 것, 목표와 메모, 지금까지의 이야기. /eui tour journal 명령으로 하나씩 보여 줍니다.",
	["Your character's story in a few lines, with the level river, your numbers, the eras, and ways to share it."] = "몇 줄로 보는 캐릭터 이야기: 레벨 흐름, 내 수치, 시대, 공유 방법.",
	["Your character's story in a few pages."] = "몇 페이지로 보는 캐릭터 이야기.",
	["Your characters"] = "내 캐릭터",
	["Your characters and how far each one is (Alts module)."] = "내 캐릭터와 각각의 진행도 (캐릭터 모듈).",
	["your class"] = "내 직업",
	["Your class (Sets for my class only), all classes or one other class."] = "내 직업(내 직업 세트만), 모든 직업 또는 다른 직업 하나.",
	["Your class can't use it"] = "내 직업은 사용할 수 없음",
	["Your class can't use this"] = "내 직업은 이것을 사용할 수 없음",
	["Your DPS with what you wear, the damage of each ability, what one more point of each stat is worth, and what the simulator read."] = "착용 장비로 낸 DPS, 각 능력의 피해, 각 능력치 1점의 가치, 시뮬레이터가 읽은 것.",
	["Your DPS: %.1f ± %.1f (estimate)"] = "내 DPS: %.1f ± %.1f (추정)",
	["Your factions with your standing. Pick one to see what it sells and gives at each standing."] = "내 평판과 등급. 하나를 고르면 등급별로 팔거나 주는 것을 봅니다.",
	["Your filters hide all %d drops."] = { other = "필터 때문에 전리품 %d개가 모두 숨겨졌습니다." },
	["Your filters hide every attunement. Show finished attunements?"] = "필터 때문에 모든 입장 자격이 숨겨졌습니다. 완료한 입장 자격을 보시겠습니까?",
	["Your first attunement step is open:"] = "첫 입장 자격 단계가 열렸습니다:",
	["Your first attunement step."] = "첫 입장 자격 단계.",
	["Your first boss kill."] = "첫 우두머리 처치.",
	["Your first dungeon is waiting. These fit your level:"] = "첫 던전이 기다립니다. 내 레벨에 맞는 곳:",
	["Your first epic find."] = "첫 영웅 아이템 발견.",
	["Your first mount comes from your race's mount vendor once you have the level and the gold it asks for."] = "첫 탈것은 레벨과 필요한 골드를 갖추면 종족 탈것 상인에게서 삽니다.",
	["Your first mount comes from your race's mount vendor once you have the level and the gold it asks for. Meanwhile:"] = "첫 탈것은 레벨과 필요한 골드를 갖추면 종족 탈것 상인에게서 삽니다. 그동안에는:",
	["Your first mount."] = "첫 탈것.",
	["Your Forever Journal history for this character is now in My Adventure (%s)."] = "이 캐릭터의 Forever Journal 기록이 이제 나의 모험에 있습니다 (%s).",
	["Your gear is better for %s"] = "내 장비가 %s에 더 좋음",
	["Your group"] = "내 파티",
	["Your group is small for a %d-player dungeon."] = "%d인 던전에 비해 파티가 작습니다.",
	["Your hearthstone is set to %s."] = "귀환석 위치: %s.",
	["Your honor, marks and rank. Costs show once you have visited the vendor."] = "명예, 증표, 계급. 상인을 방문하면 비용이 나옵니다.",
	["Your journal"] = "내 일지",
	["Your journal as it is now is backed up first either way."] = "어느 쪽이든 지금의 일지를 먼저 백업합니다.",
	["Your journal as it is now is backed up first."] = "현재 상태의 일지를 먼저 백업합니다.",
	["Your journal is back as it was then."] = "일지가 그때 상태로 돌아왔습니다.",
	["Your journal starts today"] = "일지는 오늘부터 시작합니다",
	["Your last run took %s."] = "지난번에는 %s 걸렸습니다.",
	["Your level"] = "내 레벨",
	["Your levels while you were grouped with them."] = "그들과 파티를 하던 동안의 내 레벨.",
	["Your loot journal, Best in Slot planner and wishlist in one window. This short tour shows each part; Skip ends it, and Start tour on the settings page brings it back."] = "전리품 일지, Best in Slot 계획표, 위시리스트를 한 창에. 이 짧은 안내가 각 부분을 보여 줍니다. 건너뛰기를 누르면 끝나고, 설정 페이지의 안내 시작으로 다시 볼 수 있습니다.",
	["Your loot list"] = "내 전리품 목록",
	["Your name, or the pronoun you pick. Exports always use your name."] = "내 이름, 또는 고른 대명사. 내보내기에는 항상 이름을 씁니다.",
	["Your note"] = "내 메모",
	["Your note on \"%s\" (up to %d letters; empty removes it):"] = "“%s”에 대한 메모 (최대 %d자, 비우면 삭제):",
	["Your note on them, kept in Player Notes and shown on their tooltip."] = "그들에 대한 내 메모. 플레이어 메모에 저장되고 툴팁에 나옵니다.",
	["Your note, from Player Notes"] = "플레이어 메모의 내 메모",
	["Your note: %s"] = "내 메모: %s",
	["Your notes."] = "내 메모.",
	["Your own level times show here once you have a few levels behind you."] = "레벨을 몇 개 올리면 내 레벨별 시간이 여기에 나옵니다.",
	["your own list"] = "내 목록",
	["Your own plan. Click a slot to pick items; right-click the chip to rename it."] = "내 계획. 부위를 클릭해 아이템을 고르고, 칩을 오른쪽 클릭하면 이름을 바꿉니다.",
	["Your own side's factions, or the other side's (to see what they get)."] = "내 진영의 평판, 또는 다른 진영의 평판 (그들이 얻는 것 보기).",
	["Your pet is not out. Call it and press Sim again."] = "소환수가 나와 있지 않습니다. 부르고 Sim을 다시 누르세요.",
	["Your plan sets are empty. Pick items for them on the Best in Slot page or in the Planner tab."] = "계획 세트가 비어 있습니다. Best in Slot 페이지나 계획표 탭에서 아이템을 고르세요.",
	["Your plan sets are shared with the Best in Slot page. Rename them there."] = "계획 세트는 Best in Slot 페이지와 공유됩니다. 이름은 거기서 바꾸세요.",
	["Your professions come first with your skill. Open your profession window once so known recipes and their colors show."] = "전문기술이 숙련도와 함께 먼저 나옵니다. 아는 제조법과 색을 보려면 전문기술 창을 한 번 여세요.",
	["your quest log"] = "퀘스트 목록",
	["Your quest log is empty"] = "퀘스트 목록이 비어 있음",
	["Your quest log is empty."] = "퀘스트 목록이 비어 있습니다.",
	["Your quest log now, with where and when you took each quest."] = "지금의 퀘스트 목록, 각 퀘스트를 받은 장소와 시간 포함.",
	["Your quests here: %s."] = { other = "이곳의 내 퀘스트: %s." },
	["Your race can't use it"] = "내 종족은 사용할 수 없음",
	["Your runs"] = "내 공략 기록",
	["Your runs here: first visit, time inside, bosses beaten, who came along, and what is still to do."] = "이곳의 공략 기록: 첫 방문, 안에 있던 시간, 처치한 우두머리, 함께 간 사람, 아직 할 일.",
	["Your runs there"] = "그곳의 공략 기록",
	["Your screenshot key: %s."] = "스크린샷 키: %s.",
	["Your sets are simulated. Open the Sets tab to compare them."] = "세트 시뮬레이션이 끝났습니다. 세트 탭을 열어 비교하세요.",
	["Your side"] = "내 진영",
	["Your skill: %d"] = "내 숙련도: %d",
	["your spec"] = "내 전문화",
	["Your spec, the armor you wear and where gear may come from. This one list counts everywhere: For You, tooltips and roll advice."] = "내 전문화, 착용하는 방어구, 장비를 얻을 곳. 이 목록 하나가 모든 곳에 적용됩니다: 나를 위한 추천, 툴팁, 주사위 조언.",
	["Your story as it happened: chapters by level, day, or zone, with keepsakes, finds, and pinned notes."] = "일어난 그대로의 이야기: 레벨, 날짜 또는 지역별 장, 기념품, 발견, 고정한 메모.",
	["Your story as Markdown"] = "Markdown 형식 이야기",
	["Your story as text"] = "텍스트 형식 이야기",
	["Your story chapter by chapter: levels, places, first kills, finds, and the people you met. Keepsakes and the story so far sit beside it."] = "장별로 보는 이야기: 레벨, 장소, 첫 처치, 발견, 만난 사람들. 기념품과 지금까지의 이야기가 옆에 있습니다.",
	["Your story from level 1 to 60 as a book in chapters, in the tone you choose, with a cover for every part."] = "1에서 60레벨까지의 이야기를 고른 어조로, 부마다 표지가 있는 장별 책으로.",
	["Your story in chapters, page by page."] = "페이지마다 넘기는 장별 이야기.",
	["Your story in chapters, written from what the journal recorded."] = "일지가 기록한 내용으로 쓴 장별 이야기.",
	["Your story starts with the first thing the journal writes down."] = "이야기는 일지가 처음 기록하는 것부터 시작합니다.",
	["your talents"] = "내 특성",
	["Your target."] = "내 대상.",
	["Your two plan sets (the same as on the Best in Slot page). Click a slot to pick an item or drop one from your bags."] = "내 계획 세트 두 개 (Best in Slot 페이지와 같음). 부위를 클릭해 아이템을 고르거나 가방에서 끌어다 놓으세요.",
	["Your whole story, chapter by chapter."] = "장별로 보는 전체 이야기.",
	["Your whole story, place by place."] = "장소별로 보는 전체 이야기.",
	["Your whole story, with the keepsakes in their place."] = "기념품이 제자리에 있는 전체 이야기.",
	["Your wishlist alerts you when the item drops."] = "아이템이 나오면 위시리스트가 알려 줍니다.",
	["Your wishlist is empty"] = "위시리스트가 비어 있음",
	["Zandalar Tribe"] = "잔달라 부족",
	["Zone"] = "지역",
	["Zone Info"] = "Zone Info",
	["Zone list"] = "지역 목록",
	["Zone map"] = "지역 지도",
	["Zone Quests"] = "지역 퀘스트",
	["Zone quests come from EldoUI_LootData. Install that folder next to EldoUI to see every zone; until then only the quests the game showed you are listed."] = "지역 퀘스트는 EldoUI_LootData에서 가져옵니다. 모든 지역을 보려면 이 폴더를 EldoUI 옆에 설치하세요. 그때까지는 게임이 보여 준 퀘스트만 표시됩니다.",
	["Zone: %s"] = "지역: %s",
	["Zone: All"] = "지역: 전체",
	["Zones"] = "지역",
	["Zones and dungeons."] = "지역과 던전.",
	["Zones and mobs"] = "지역과 몹",
	["Zones for your level"] = "내 레벨에 맞는 지역",
	["Zones for your level or all zones. The guide follows your zone until you click one."] = "내 레벨에 맞는 지역 또는 모든 지역. 지역을 클릭하기 전까지 가이드는 현재 지역을 따라갑니다.",
	["Zones for your level, or every zone the loot data knows creatures for."] = "내 레벨에 맞는 지역, 또는 전리품 데이터가 몹을 아는 모든 지역.",
	["Zones with quests for your level that you have not done yet."] = "아직 하지 않은 내 레벨 퀘스트가 있는 지역.",
	["Zoom in"] = "확대",
	["Zoom out"] = "축소",
	["Zooms so the whole chain fits the window."] = "연계 전체가 창에 들어가도록 확대/축소합니다.",
	["Zul'Gurub sets"] = "줄구룹 세트",
	["~%s to %d"] = "~%s 후 %d레벨",
	["Drag to make the window bigger or smaller; the content follows. Ctrl+mouse wheel on the title bar zooms."] = "끌어서 창을 키우거나 줄입니다. 내용이 함께 맞춰집니다. 제목 표시줄에서 Ctrl+마우스 휠로 확대/축소합니다.",
	["Window size"] = "창 크기",
	["Opens at level %d in %s."] = "%d 레벨부터 %s에서 시작합니다.",
	["Opens at level %d with %s in %s."] = "%d레벨부터 %s에게서 시작합니다 (%s).",
	["Opens at level %d."] = "%d레벨부터 시작합니다.",
	["It ends with %s."] = "마지막 보상: %s.",
	["Tracks whether you have the Dalaran Sewer Key. One key holder can open the gate for the group; you do not need to finish the dungeon quest first."] = "달라란 하수도 열쇠 보유 여부를 표시합니다. 열쇠를 가진 한 명이 파티를 위해 문을 열 수 있으며, 먼저 던전 퀘스트를 완료할 필요는 없습니다.",
	["%d more drops were not kept."] = { other = "그 밖의 아이템 %d개는 저장되지 않았습니다." },
	["%s runs"] = { other = "공략 %s회" },
	["%s runs added to your journal."] = { other = "공략 %s회를 일지에 추가했습니다." },
	["Accept merges them into this character's runs: nothing is lost, and a backup is taken first."] = "수락하면 이 캐릭터의 공략 기록에 합칩니다: 아무것도 잃지 않으며, 먼저 백업을 만듭니다.",
	["An item"] = "아이템",
	["Attunement lines on item and character tooltips have their own switches on the Tooltip page."] = "아이템 및 캐릭터 툴팁의 입장 자격 줄은 툴팁 페이지에 각자의 스위치가 있습니다.",
	["Attunements, keys and dungeon quest chains as a Loot Guide tab. Progress comes from your quest log, bags and reputation."] = "입장 자격, 열쇠, 던전 연계 퀘스트를 Loot Guide의 탭으로. 진행도는 퀘스트 목록, 가방, 평판에서 가져옵니다.",
	["Backups are copies of this journal in your saved data. The game writes them to disk when you log out or /reload."] = "백업은 저장된 데이터 안에 있는 이 일지의 사본입니다. 게임은 로그아웃하거나 /reload할 때 디스크에 기록합니다.",
	["Backups of your runs"] = "공략 기록 백업",
	["Classic: chances from Classic data; Forever may differ. Seen: what you looted yourself, with the number of kills (needs Mob and Loot Info)."] = "클래식: 클래식 데이터의 확률이며 Forever와 다를 수 있습니다. 봄: 직접 획득한 것과 처치 수 (몹 및 전리품 정보 필요).",
	["Copy a runs code"] = "공략 코드 복사",
	["Creatures that can drop an item that starts a quest get a tooltip line and a small icon on their nameplate."] = "퀘스트를 시작하는 아이템을 떨어뜨릴 수 있는 생물은 툴팁에 한 줄, 이름표에 작은 아이콘이 붙습니다.",
	["Delete this run?"] = "이 공략을 삭제할까요?",
	["Every dungeon and raid run stays in your journal with who was in it. Its own code keeps them safe or moves them to another PC."] = "모든 던전 및 공격대 공략은 함께한 사람과 함께 일지에 남습니다. 전용 코드로 안전하게 보관하거나 다른 PC로 옮길 수 있습니다.",
	["Every zone's quests in the Loot Guide's Catalog: how many you have done, what is left and who gives them."] = "Loot Guide 목록의 지역별 퀘스트: 완료한 수, 남은 것, 퀘스트를 주는 사람.",
	["Everyone passed"] = "모두 포기",
	["For this character: your stat weights (fast, the same as the Upgrades arrows), or the simulator (DPS against a target dummy, run when you press Sim)."] = "이 캐릭터 기준: 능력치 가중치(빠름, 업그레이드 화살표와 같음) 또는 시뮬레이터(훈련용 허수아비 상대 DPS, Sim을 누르면 실행).",
	["Forget"] = "잊기",
	["Forget this name?"] = "이 이름을 잊을까요?",
	["Green is done, the accent is in your quest log, yellow is available, gray is locked. An unreported step counts once the next is done."] = "초록색은 완료, 강조 색상은 퀘스트 목록에 있음, 노란색은 가능, 회색은 잠김. 보고되지 않은 단계는 다음 단계를 마치면 완료로 칩니다.",
	["Journal run backups of %s"] = "%s의 일지 공략 백업",
	["Journal runs backup"] = "일지 공략 백업",
	["Journal runs of %s"] = "%s의 일지 공략",
	["Load the runs of %s (saved %s) into this character?"] = "%s의 공략 기록(%s에 저장)을 이 캐릭터로 불러올까요?",
	["Loads a runs code (!EUJR1!). You see what it holds, then Merge or Replace."] = "공략 코드(!EUJR1!)를 불러옵니다. 내용을 확인한 뒤 합치기나 바꾸기를 고릅니다.",
	["Loot Guide in EldoUI %s. %s opens the window, %s the simulator, %s lists every command."] = "EldoUI %s의 Loot Guide. %s: 창 열기, %s: 시뮬레이터, %s: 모든 명령어 목록.",
	["Merge adds the runs your journal is missing and never adds one twice. Replace puts your runs back exactly as they were then."] = "합치기는 일지에 없는 공략을 더하고 같은 공략을 두 번 넣지 않습니다. 바꾸기는 공략 기록을 정확히 그때 상태로 되돌립니다.",
	["Need (off spec)"] = "입찰(부 전문화)",
	["No backup of your runs yet."] = "아직 공략 기록 백업이 없습니다.",
	["No roll"] = "주사위 없음",
	["Nothing to read. Paste a runs code first."] = "읽을 내용이 없습니다. 먼저 공략 코드를 붙여 넣으세요.",
	["On a creature that can drop an item that starts a quest: the item, the quest and the drop chance, until you have the item or did the quest."] = "퀘스트를 시작하는 아이템을 떨어뜨릴 수 있는 생물 위에서: 아이템, 퀘스트, 획득 확률. 아이템을 얻거나 퀘스트를 마칠 때까지 표시됩니다.",
	["Paste a runs code"] = "공략 코드 붙여 넣기",
	["Paste a runs code from EldoUI (!EUJR1!). You see what it holds before anything changes."] = "EldoUI의 공략 코드(!EUJR1!)를 붙여 넣으세요. 무엇이 바뀌기 전에 내용을 먼저 봅니다.",
	["Pick a backup of your runs, then Merge or Replace. Your runs are backed up first."] = "공략 기록 백업을 고른 뒤 합치기나 바꾸기를 고르세요. 공략 기록은 먼저 백업됩니다.",
	["Press Ctrl+C to copy the code. Use \"Paste a runs code\" on this PC or another to restore your runs. Nothing is sent anywhere."] = "Ctrl+C로 코드를 복사하세요. 이 PC나 다른 PC에서 \"공략 코드 붙여 넣기\"를 사용하면 공략 기록을 복원합니다. 어디로도 보내지 않습니다.",
	["Restore your runs"] = "공략 기록 복원",
	["Restore your runs from %s?"] = "%s의 공략 기록을 복원할까요?",
	["Runs code"] = "공략 코드",
	["Show %d earlier runs"] = { other = "이전 공략 %d개 보기" },
	["Someone"] = "누군가",
	["That is not a runs code. A runs code starts with !EUJR1!."] = "공략 코드가 아닙니다. 공략 코드는 !EUJR1!로 시작합니다.",
	["The name leaves every run and your companions; the runs and everyone else stay. Undo brings it back for 7 days."] = "이 이름이 모든 공략과 동료에서 빠집니다. 공략과 다른 사람은 그대로 남습니다. 되돌리기로 7일 동안 복구할 수 있습니다.",
	["The run leaves your journal; everything else stays. Undo brings it back for 7 days."] = "이 공략이 일지에서 빠집니다. 나머지는 그대로 남습니다. 되돌리기로 7일 동안 복구할 수 있습니다.",
	["The runs of %s, saved %s."] = "%s의 공략 기록, 저장: %s.",
	["The tooltip line has its own switch on the Tooltip page. The chance follows the Loot Guide's Drop chances setting."] = "툴팁 줄은 툴팁 페이지에 자체 스위치가 있습니다. 확률은 Loot Guide의 획득 확률 설정을 따릅니다.",
	["There are no runs to back up yet."] = "아직 백업할 공략이 없습니다.",
	["This can be done out of combat only."] = "전투 중에는 할 수 없습니다.",
	["Transmog"] = "형상변환",
	["Updating the list of runs. It fills in by itself in a moment."] = "공략 목록을 갱신하는 중입니다. 잠시 후 저절로 채워집니다.",
	["What the pages show; everything is always written down. Essentials: levels, deaths, notes, goals. Storyteller: adds spells, professions and places. Chronicler: everything."] = "페이지에 보이는 내용이며, 기록은 항상 전부 남습니다. 핵심: 레벨, 죽음, 메모, 목표. 이야기꾼: 주문, 전문 기술, 장소 추가. 연대기 작가: 전부.",
	["with %s others"] = { other = "다른 %s명과 함께" },
	["Won with you"] = "함께 획득",
	["Your character's journal in the Journal window: a diary that writes itself, keepsakes, places, quests, goals and notes, your story from 1 to 60 and where to go next."] = "일지 창의 캐릭터 일지: 스스로 쓰이는 일기, 기념품, 장소, 퀘스트, 목표, 메모, 1레벨부터 60레벨까지의 이야기와 다음에 갈 곳.",
	["Your runs are back as they were then."] = "공략 기록이 그때 상태로 돌아왔습니다.",
	["Your runs as one code, to keep or to paste in on another PC. Nothing is sent anywhere."] = "공략 기록 전체를 코드 하나로. 보관하거나 다른 PC에 붙여 넣을 수 있습니다. 아무 데도 보내지 않습니다.",
	["Your runs as they are now are backed up first either way."] = "어느 쪽이든 지금의 공략 기록을 먼저 백업합니다.",
} end)
